void AddAudioEvent(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();

    if (!isInitialised()) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return;
    }

    if (info.Length() < 3 || !info[0].IsNumber() || !info[1].IsNumber() || !info[2].IsNumber()) {
        JsonApi::TypeError::New(env, "addAudioEvent(beatPosition: number, sampleId: number, velocity: number)")
            .ThrowAsJavaScriptException();
        return;
    }

    AudioEvent ev;
    ev.beatPosition = info[0].As<JsonApi::Number>().DoubleValue();
    ev.sampleId     = info[1].As<JsonApi::Number>().Int32Value();
    ev.velocity     = info[2].As<JsonApi::Number>().FloatValue();
    audioEngine->getAudioScheduler().addEvent(ev);
}

void AddVideoEvent(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();

    if (!isInitialised()) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return;
    }

    if (!syncManager) return;

    if (info.Length() < 1 || !info[0].IsObject()) {
        JsonApi::TypeError::New(env, "addVideoEvent({ startBeat, durationBeats, sourceId, "
                                  "sourceStartTime, layerIndex, x, y, width, height, opacity })")
            .ThrowAsJavaScriptException();
        return;
    }

    JsonApi::Object o = info[0].As<JsonApi::Object>();

    VideoEvent ev;
    ev.startBeat       = o.Get("startBeat").As<JsonApi::Number>().DoubleValue();
    ev.durationBeats   = o.Get("durationBeats").As<JsonApi::Number>().DoubleValue();
    ev.sourceId        = o.Get("sourceId").As<JsonApi::Number>().Int32Value();
    ev.sourceStartTime = o.Get("sourceStartTime").As<JsonApi::Number>().DoubleValue();
    ev.sourceClampStartTime = ev.sourceStartTime;
    ev.layerIndex      = o.Get("layerIndex").As<JsonApi::Number>().Int32Value();
    ev.x       = o.Get("x").As<JsonApi::Number>().FloatValue();
    ev.y       = o.Get("y").As<JsonApi::Number>().FloatValue();
    ev.width   = o.Get("width").As<JsonApi::Number>().FloatValue();
    ev.height  = o.Get("height").As<JsonApi::Number>().FloatValue();
    ev.opacity = o.Get("opacity").As<JsonApi::Number>().FloatValue();

    {
        std::lock_guard<std::recursive_mutex> lock(syncEventsMutex);
        syncManager->addEvent(ev);
    }
}

void ClearTimeline(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();

    if (!isInitialised()) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return;
    }

    audioEngine->getAudioScheduler().clearEvents();

    {
        std::lock_guard<std::recursive_mutex> lock(syncEventsMutex);
        if (syncManager) syncManager->clearEvents();

        for (auto& d : decoderOwner)
            d->close();
        decoderOwner.clear();
        decoderPtrs.clear();
    }
    // Events are gone; the video thread must rebuild them before it can draw.
    g_videoEventsDirty.store(true, std::memory_order_release);

    if (frameCache) frameCache->clear();

    // [PreviewUnify] Clear GPU render pipeline state
    {
        std::lock_guard<std::mutex> lock(g_previewCompositorMutex);
        if (g_previewRenderCache)   g_previewRenderCache->clear();
        if (g_previewRenderDecoder) g_previewRenderDecoder->closeAll();
    }

    if (frameOutput.isInitialized()) frameOutput.writeBlackFrame();
}

