JsonApi::Value GetSyncStats(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    JsonApi::Object obj = JsonApi::Object::New(env);

    StatsSnapshot snap;
    {
        std::lock_guard<std::mutex> lock(statsMutex);
        snap = statsSnapshot;
    }

    obj.Set("avgDriftMs",   JsonApi::Number::New(env, snap.avgDriftMs));
    obj.Set("maxDriftMs",   JsonApi::Number::New(env, snap.maxDriftMs));
    obj.Set("frameDrops",   JsonApi::Number::New(env, snap.frameDrops));
    obj.Set("cacheHitRate", JsonApi::Number::New(env, snap.cacheHitRate));
    return obj;
}

