// timeline_addTrack({ name, volume?, pan?, muted?, solo?, order? }) → id
JsonApi::Value Timeline_AddTrack(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsObject()) {
        JsonApi::TypeError::New(env, "timeline_addTrack({ name, volume?, pan?, muted?, solo?, order? })")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    BridgeCallLog log("timeline.addTrack");

    TrackInfo t = jsToTrack(info[0].As<JsonApi::Object>());
    g_undoManager->execute(std::make_unique<AddTrackCommand>(t), *g_timeline);
    syncMixerTrackSlots(false);

    // The newly added track always has the highest ID; getAllTracks() returns
    // visible timeline order, so compute the max explicitly.
    auto tracks = g_timeline->getAllTracks();
    int newId = -1;
    for (const auto* track : tracks) {
        if (track)
            newId = std::max(newId, track->id);
    }
    log.done(std::to_string(newId));
    return JsonApi::Number::New(env, newId);
}

// timeline_removeTrack(id) — cascades to clips on that track
void Timeline_RemoveTrack(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return;
    }
    if (info.Length() < 1 || !info[0].IsNumber()) {
        JsonApi::TypeError::New(env, "timeline_removeTrack(id: number)").ThrowAsJavaScriptException();
        return;
    }
    int id = info[0].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("timeline.removeTrack");
    // Abandon any in-flight drag whose clip lives on the track going away (or
    // whose clip has already vanished). Sessions on other tracks are untouched.
    for (auto it = g_clipControlEdits.begin(); it != g_clipControlEdits.end(); ) {
        const Clip* editedClip = g_timeline->getClip(it->second.clipId);
        if (!editedClip || editedClip->trackId == id) {
            restoreClipControlEditSession(it->second);
            it = g_clipControlEdits.erase(it);
        } else {
            ++it;
        }
    }
    {
        // Cascades into grid slots / chorus / crash — hold syncEventsMutex
        // so the video thread sees a consistent GridLayout.
        std::lock_guard<std::recursive_mutex> lock(syncEventsMutex);
        g_undoManager->execute(std::make_unique<RemoveTrackCommand>(id, *g_timeline), *g_timeline);
    }
    // Close any open plugin editor windows for this track before tearing it down.
    if (audioEngine) audioEngine->getMixEngine().closePluginEditorsForTrack(id);
    // Release every sampler pair this track owned (no-op if it was a clip track).
    if (audioEngine) audioEngine->getMixEngine().unloadSamplersForTrack(id);
    syncMixerTrackSlots(false);
    log.done();
}

// ─── jsToClip ─────────────────────────────────────────────────────────────────
// Single source of truth for JS-object → Clip unmarshalling. Timeline_AddClip
// and Timeline_AddClipsBatch both go through it, so the batch path can never
// again silently drop fields the single-add path understands (it used to read
// 7 of these ~25, which is why copy/paste could not use it).
static Clip jsToClip(const JsonApi::Object& o)
{
    Clip clip;
    clip.trackId         = o.Get("trackId").As<JsonApi::Number>().Int32Value();
    clip.regionId        = o.Get("regionId").As<JsonApi::Number>().Int32Value();
    clip.position.ticks  = static_cast<int64_t>(o.Get("positionTicks").As<JsonApi::Number>().DoubleValue());
    clip.duration.ticks  = static_cast<int64_t>(o.Get("durationTicks").As<JsonApi::Number>().DoubleValue());
    if (o.Has("regionOffsetTicks") && o.Get("regionOffsetTicks").IsNumber())
        clip.regionOffset.ticks = static_cast<int64_t>(o.Get("regionOffsetTicks").As<JsonApi::Number>().DoubleValue());
    if (o.Has("syllableIndex") && o.Get("syllableIndex").IsNumber())
        clip.syllableIndex = o.Get("syllableIndex").As<JsonApi::Number>().Int32Value();
    if (o.Has("pitchOffset") && o.Get("pitchOffset").IsNumber())
        clip.pitchOffset = o.Get("pitchOffset").As<JsonApi::Number>().Int32Value();
    if (o.Has("velocity") && o.Get("velocity").IsNumber())
        clip.velocity = o.Get("velocity").As<JsonApi::Number>().FloatValue();
    if (o.Has("pitchOffsetCents") && o.Get("pitchOffsetCents").IsNumber()) {
        int cents = o.Get("pitchOffsetCents").As<JsonApi::Number>().Int32Value();
        clip.pitchOffsetCents = std::max(-99, std::min(99, cents));
    }
    if (o.Has("reversed") && o.Get("reversed").IsBoolean())
        clip.reversed = o.Get("reversed").As<JsonApi::Boolean>().Value();
    if (o.Has("stretchRatio") && o.Get("stretchRatio").IsNumber()) {
        double ratio = o.Get("stretchRatio").As<JsonApi::Number>().DoubleValue();
        clip.stretchRatio = (ratio <= 0.0) ? 1.0 : ratio;
    }
    if (o.Has("stretchMethod") && o.Get("stretchMethod").IsNumber()) {
        int sm = o.Get("stretchMethod").As<JsonApi::Number>().Int32Value();
        clip.stretchMethod = static_cast<StretchMethod>(
            (sm >= 0 && sm <= 5) ? sm : 0 /*Global*/);
    }
    if (o.Has("formantPreserve") && o.Get("formantPreserve").IsBoolean())
        clip.formantPreserve = o.Get("formantPreserve").As<JsonApi::Boolean>().Value();

    // Fade envelope — optional, mirrors Timeline_SetClipParams field handling.
    // Legacy tick fields are converted to percentages using the clip duration.
    if (o.Has("fadeInPercent") && o.Get("fadeInPercent").IsNumber())
        clip.fadeInPercent = o.Get("fadeInPercent").As<JsonApi::Number>().FloatValue();
    else if (o.Has("fadeInTicks") && o.Get("fadeInTicks").IsNumber())
        clip.fadeInPercent = legacyFadeTicksToPercent(
            o.Get("fadeInTicks").As<JsonApi::Number>().FloatValue(), clip.duration.ticks);
    if (o.Has("fadeOutPercent") && o.Get("fadeOutPercent").IsNumber())
        clip.fadeOutPercent = o.Get("fadeOutPercent").As<JsonApi::Number>().FloatValue();
    else if (o.Has("fadeOutTicks") && o.Get("fadeOutTicks").IsNumber())
        clip.fadeOutPercent = legacyFadeTicksToPercent(
            o.Get("fadeOutTicks").As<JsonApi::Number>().FloatValue(), clip.duration.ticks);
    normalizeClipFadePercents(clip);
    if (o.Has("fadeInX1")  && o.Get("fadeInX1").IsNumber())  clip.fadeInX1  = o.Get("fadeInX1").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeInY1")  && o.Get("fadeInY1").IsNumber())  clip.fadeInY1  = o.Get("fadeInY1").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeInX2")  && o.Get("fadeInX2").IsNumber())  clip.fadeInX2  = o.Get("fadeInX2").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeInY2")  && o.Get("fadeInY2").IsNumber())  clip.fadeInY2  = o.Get("fadeInY2").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeOutX1") && o.Get("fadeOutX1").IsNumber()) clip.fadeOutX1 = o.Get("fadeOutX1").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeOutY1") && o.Get("fadeOutY1").IsNumber()) clip.fadeOutY1 = o.Get("fadeOutY1").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeOutX2") && o.Get("fadeOutX2").IsNumber()) clip.fadeOutX2 = o.Get("fadeOutX2").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeOutY2") && o.Get("fadeOutY2").IsNumber()) clip.fadeOutY2 = o.Get("fadeOutY2").As<JsonApi::Number>().FloatValue();

    // Clip modulation (Vibrato / Scratch / Video swirl-scratch) — optional.
    // Carried by copy/paste & duplicate so those operations preserve Swirl and
    // Scratch data. Parsed from a default-constructed base so any absent nested
    // field falls back to the engine default rather than leaking another clip's
    // state; a present `modulation` object round-trips clipModulationToJs.
    if (o.Has("modulation") && o.Get("modulation").IsObject())
        clip.modulation = jsToClipModulation(
            o.Get("modulation").As<JsonApi::Object>(), ClipModulation{});

    // Lens: absent = a NEW clip (Clip{} default, fit = Cover); present = a
    // rebuilt clip (paste / split / duplicate) keeping the lens clipToJs
    // emitted. Tolerant reader, the project-load one.
    if (o.Has("lens") && o.Get("lens").IsObject())
        clip.lens = lensroam::lensTrackFromJson(valueToJson(o.Get("lens")));

    return clip;
}

// timeline_addClip({ trackId, regionId, positionTicks, durationTicks,
//                    regionOffsetTicks?, syllableIndex?, velocity?, pitchOffset?,
//                    pitchOffsetCents?, reversed?, stretchRatio?, stretchMethod?, formantPreserve?,
//                    fadeInPercent?, fadeOutPercent?, fadeInX1?, fadeInY1?, fadeInX2?, fadeInY2?,
//                    fadeOutX1?, fadeOutY1?, fadeOutX2?, fadeOutY2?,
//                    modulation? }) → id
JsonApi::Value Timeline_AddClip(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsObject()) {
        JsonApi::TypeError::New(env, "timeline_addClip({ trackId, regionId, positionTicks, durationTicks, velocity? })")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    BridgeCallLog log("timeline.addClip");

    JsonApi::Object o = info[0].As<JsonApi::Object>();
    Clip clip = jsToClip(o);

#ifdef XLETH_DEBUG
    // Per-field "present/defaulted" map — reveals whether a missing JS key
    // or a wrong type (IsNumber/IsBoolean guard failure) caused a default.
    auto presence = [&](const char* key) -> const char* {
        if (!o.Has(key))                    return "MISSING";
        auto v = o.Get(key);
        if (v.IsUndefined() || v.IsNull())  return "undef/null";
        if (v.IsNumber())                   return "number";
        if (v.IsBoolean())                  return "bool";
        return "OTHER-TYPE";
    };
    fprintf(stderr,
        "[XlethAddon_AddClip] presence: regionOffsetTicks=%s syllableIndex=%s "
        "pitchOffset=%s pitchOffsetCents=%s reversed=%s stretchRatio=%s "
        "stretchMethod=%s formantPreserve=%s velocity=%s "
        "fadeInPercent=%s fadeOutPercent=%s legacyFadeInTicks=%s legacyFadeOutTicks=%s "
        "fadeInX1=%s fadeInY1=%s fadeInX2=%s fadeInY2=%s "
        "fadeOutX1=%s fadeOutY1=%s fadeOutX2=%s fadeOutY2=%s\n",
        presence("regionOffsetTicks"), presence("syllableIndex"),
        presence("pitchOffset"),       presence("pitchOffsetCents"),
        presence("reversed"),          presence("stretchRatio"),
        presence("stretchMethod"),     presence("formantPreserve"),
        presence("velocity"),
        presence("fadeInPercent"),     presence("fadeOutPercent"),
        presence("fadeInTicks"),       presence("fadeOutTicks"),
        presence("fadeInX1"),          presence("fadeInY1"),
        presence("fadeInX2"),          presence("fadeInY2"),
        presence("fadeOutX1"),         presence("fadeOutY1"),
        presence("fadeOutX2"),         presence("fadeOutY2"));
    fprintf(stderr,
        "[XlethAddon_AddClip] received: trackId=%d regionId=%d pos=%lld dur=%lld "
        "pitchOffset=%d pitchCents=%d reversed=%d stretchRatio=%.3f "
        "stretchMethod=%d formantPreserve=%d velocity=%.3f "
        "fadeIn=%.2f fadeOut=%.2f bezierIn=[%.2f,%.2f,%.2f,%.2f] "
        "bezierOut=[%.2f,%.2f,%.2f,%.2f]\n",
        clip.trackId, clip.regionId,
        (long long)clip.position.ticks, (long long)clip.duration.ticks,
        clip.pitchOffset, clip.pitchOffsetCents,
        clip.reversed ? 1 : 0, clip.stretchRatio,
        (int)clip.stretchMethod, clip.formantPreserve ? 1 : 0, clip.velocity,
        clip.fadeInPercent, clip.fadeOutPercent,
        clip.fadeInX1, clip.fadeInY1, clip.fadeInX2, clip.fadeInY2,
        clip.fadeOutX1, clip.fadeOutY1, clip.fadeOutX2, clip.fadeOutY2);
    fflush(stderr);
#endif

    g_undoManager->execute(std::make_unique<AddClipCommand>(clip), *g_timeline);

    auto clips = g_timeline->getAllClips();
    int newId = clips.empty() ? -1 : clips.back()->id;

    if (audioEngine && newId >= 0)
        audioEngine->getMixEngine().invalidateClipCache(newId, "addClip");

    // Trigger on-demand region proxy generation if this clip is on a
    // non-Chorus / non-Crash cell. No-op when region already has a ready proxy.
    maybeEnqueueRegionProxy(clip.regionId, clip.trackId);

    log.done(std::to_string(newId));
    return JsonApi::Number::New(env, newId);
}

// timeline_addClipsBatch([{ ...same shape as timeline_addClip... }, ...]) → [id, ...]
// Inserts N clips as a single undoable command and a single RPC round trip.
// Field handling is shared with timeline_addClip via jsToClip(), so paste /
// duplicate keep stretch, pitch, fades and modulation intact.
JsonApi::Value Timeline_AddClipsBatch(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsArray()) {
        JsonApi::TypeError::New(env, "timeline_addClipsBatch(clips: Array)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    BridgeCallLog log("timeline.addClipsBatch");

    JsonApi::Array arr = info[0].As<JsonApi::Array>();
    std::vector<Clip> clips;
    clips.reserve(arr.Length());

    for (uint32_t i = 0; i < arr.Length(); i++) {
        if (!arr.Get(i).IsObject()) continue;
        clips.push_back(jsToClip(arr.Get(i).As<JsonApi::Object>()));
    }

    if (clips.empty()) {
        log.done("0");
        return JsonApi::Array::New(env, 0);
    }

    // Distinct regions touched — the proxy enqueue below is per-region, and a
    // paste routinely spans several. The old code only ever looked at clips[0].
    std::vector<std::pair<int,int>> regionTrackPairs;
    for (const auto& c : clips) {
        const std::pair<int,int> pr{c.regionId, c.trackId};
        if (std::find(regionTrackPairs.begin(), regionTrackPairs.end(), pr)
            == regionTrackPairs.end())
            regionTrackPairs.push_back(pr);
    }

    auto cmd = std::make_unique<AddClipsBatchCommand>(clips);
    AddClipsBatchCommand* cmdPtr = cmd.get();
    g_undoManager->execute(std::move(cmd), *g_timeline);

    const auto& ids = cmdPtr->getAssignedIds();
    if (audioEngine)
        audioEngine->getMixEngine().invalidateClipCaches(ids, "addClipsBatch");
    for (const auto& pr : regionTrackPairs)
        maybeEnqueueRegionProxy(pr.first, pr.second);

    JsonApi::Array result = JsonApi::Array::New(env, ids.size());
    for (size_t i = 0; i < ids.size(); i++)
        result.Set(static_cast<uint32_t>(i), JsonApi::Number::New(env, ids[i]));

    log.done(std::to_string(ids.size()));
    return result;
}

// timeline_pasteClipsBatch({ removeClipIds: [id,...], clips: [ ...addClip shape... ] })
//   → { newIds: [id,...], removedCount }
// The atomic paste: overwrite + insert as ONE undoable operation and ONE round
// trip. Splitting it into removeClipsBatch + addClipsBatch left a single Ctrl+Z
// in the half-applied state between the two halves.
JsonApi::Value Timeline_PasteClipsBatch(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsObject()) {
        JsonApi::TypeError::New(env,
            "timeline_pasteClipsBatch({ removeClipIds?: number[], clips: Array })")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    BridgeCallLog log("timeline.pasteClipsBatch");

    JsonApi::Object arg = info[0].As<JsonApi::Object>();

    std::vector<int> removeIds;
    if (arg.Has("removeClipIds") && arg.Get("removeClipIds").IsArray()) {
        JsonApi::Array r = arg.Get("removeClipIds").As<JsonApi::Array>();
        removeIds.reserve(r.Length());
        for (uint32_t i = 0; i < r.Length(); i++) {
            if (!r.Get(i).IsNumber()) continue;
            removeIds.push_back(r.Get(i).As<JsonApi::Number>().Int32Value());
        }
    }

    std::vector<Clip> clips;
    if (arg.Has("clips") && arg.Get("clips").IsArray()) {
        JsonApi::Array c = arg.Get("clips").As<JsonApi::Array>();
        clips.reserve(c.Length());
        for (uint32_t i = 0; i < c.Length(); i++) {
            if (!c.Get(i).IsObject()) continue;
            clips.push_back(jsToClip(c.Get(i).As<JsonApi::Object>()));
        }
    }

    JsonApi::Object result = JsonApi::Object::New(env);
    if (clips.empty() && removeIds.empty()) {
        result.Set("newIds", JsonApi::Array::New(env, 0));
        result.Set("removedCount", JsonApi::Number::New(env, 0));
        log.done("0");
        return result;
    }

    // Distinct region/track pairs — proxy generation is per region and a paste
    // routinely spans several.
    std::vector<std::pair<int,int>> regionTrackPairs;
    for (const auto& c : clips) {
        const std::pair<int,int> pr{c.regionId, c.trackId};
        if (std::find(regionTrackPairs.begin(), regionTrackPairs.end(), pr)
            == regionTrackPairs.end())
            regionTrackPairs.push_back(pr);
    }

    auto cmd = std::make_unique<ReplaceClipsBatchCommand>(
        std::move(removeIds), std::move(clips), *g_timeline);
    ReplaceClipsBatchCommand* cmdPtr = cmd.get();
    g_undoManager->execute(std::move(cmd), *g_timeline);

    const auto& newIds = cmdPtr->getAssignedIds();
    if (audioEngine) {
        audioEngine->getMixEngine().invalidateClipCaches(
            cmdPtr->getRemovedIds(), "pasteClipsBatch/removed");
        audioEngine->getMixEngine().invalidateClipCaches(newIds, "pasteClipsBatch");
    }
    for (const auto& pr : regionTrackPairs)
        maybeEnqueueRegionProxy(pr.first, pr.second);

    result.Set("newIds", intVectorToJs(env, newIds));
    result.Set("removedCount",
               JsonApi::Number::New(env, static_cast<int>(cmdPtr->getRemovedIds().size())));
    // Post-state, so the renderer splices instead of refetching the project:
    // `clips` are the inserted clips as the engine now holds them (ids, and any
    // field the engine normalized on the way in), `removedIds` exactly what the
    // overwrite buried. newIds/removedCount stay for callers that only needed
    // the ids — they are derivable from these but cheap to keep.
    result.Set("clips", clipsByIdToJs(env, newIds));
    result.Set("removedIds", intVectorToJs(env, cmdPtr->getRemovedIds()));

    log.done(std::to_string(newIds.size()));
    return result;
}

// timeline_moveClipsBatch([{ clipId, trackId, positionTicks }, ...])
//   → Clip[]  (post-move state of every clip that resolved)
// Repositions N clips in one undoable command and one RPC round trip.
// Dragging a multi-clip selection used to fire one moveClip per clip, each a
// full renderer→main→worker round trip AND its own undo entry.
//
// The return used to be a bare count, which forced the renderer to follow every
// move with a full timeline_getClips() — the entire project's clips, 26 scalar
// fields plus a nested modulation object each, structured-cloned across two
// process hops and then rebuilt into fresh JS objects that invalidated every
// clips-keyed memo. Handing back the post-state of the touched clips (a bounded
// set the command already knows, MoveClipsBatchCommand::getMovedIds) removes
// that refetch entirely. Same rationale for removeClipsBatch/pasteClipsBatch
// below; the unbounded refetch survives only for undo/redo and project load.
JsonApi::Value Timeline_MoveClipsBatch(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsArray()) {
        JsonApi::TypeError::New(env,
            "timeline_moveClipsBatch(moves: Array<{clipId, trackId, positionTicks}>)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    BridgeCallLog log("timeline.moveClipsBatch");

    JsonApi::Array arr = info[0].As<JsonApi::Array>();
    std::vector<MoveClipsBatchCommand::Move> moves;
    moves.reserve(arr.Length());
    for (uint32_t i = 0; i < arr.Length(); i++) {
        if (!arr.Get(i).IsObject()) continue;
        JsonApi::Object o = arr.Get(i).As<JsonApi::Object>();
        if (!o.Get("clipId").IsNumber() || !o.Get("trackId").IsNumber()
            || !o.Get("positionTicks").IsNumber()) continue;
        MoveClipsBatchCommand::Move m;
        m.clipId              = o.Get("clipId").As<JsonApi::Number>().Int32Value();
        m.newTrackId          = o.Get("trackId").As<JsonApi::Number>().Int32Value();
        m.newPosition.ticks   = static_cast<int64_t>(
            o.Get("positionTicks").As<JsonApi::Number>().DoubleValue());
        moves.push_back(m);
    }

    if (moves.empty()) { log.done("0"); return JsonApi::Array::New(env, 0); }

    auto cmd = std::make_unique<MoveClipsBatchCommand>(std::move(moves), *g_timeline);
    MoveClipsBatchCommand* cmdPtr = cmd.get();
    g_undoManager->execute(std::move(cmd), *g_timeline);

    // A move leaves every CacheKey input untouched, so this resolves to a
    // no-op for each clip — it exists only so a move that DID cross a
    // region/rate boundary still re-points the cache correctly.
    const auto& ids = cmdPtr->getMovedIds();
    if (audioEngine)
        audioEngine->getMixEngine().invalidateClipCaches(ids, "moveClipsBatch");

    log.done(std::to_string(ids.size()));
    return clipsByIdToJs(env, ids);
}

// timeline_removeClipsBatch([id, ...]) → number[]  (ids actually removed)
// Deletes N clips in one undoable command. Ctrl+Z restores the whole selection.
// Returns the ids rather than a count so the renderer can drop exactly those
// clips from its list instead of refetching the whole project.
JsonApi::Value Timeline_RemoveClipsBatch(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsArray()) {
        JsonApi::TypeError::New(env, "timeline_removeClipsBatch(ids: Array<number>)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    BridgeCallLog log("timeline.removeClipsBatch");

    JsonApi::Array arr = info[0].As<JsonApi::Array>();
    std::vector<int> ids;
    ids.reserve(arr.Length());
    for (uint32_t i = 0; i < arr.Length(); i++) {
        if (!arr.Get(i).IsNumber()) continue;
        ids.push_back(arr.Get(i).As<JsonApi::Number>().Int32Value());
    }

    if (ids.empty()) { log.done("0"); return JsonApi::Array::New(env, 0); }

    auto cmd = std::make_unique<RemoveClipsBatchCommand>(std::move(ids), *g_timeline);
    RemoveClipsBatchCommand* cmdPtr = cmd.get();
    g_undoManager->execute(std::move(cmd), *g_timeline);

    const auto& removed = cmdPtr->getRemovedIds();
    if (audioEngine)
        audioEngine->getMixEngine().invalidateClipCaches(removed, "removeClipsBatch");

    log.done(std::to_string(removed.size()));
    return intVectorToJs(env, removed);
}

// timeline_removeClip(id)
void Timeline_RemoveClip(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return;
    }
    if (info.Length() < 1 || !info[0].IsNumber()) {
        JsonApi::TypeError::New(env, "timeline_removeClip(id: number)").ThrowAsJavaScriptException();
        return;
    }
    int id = info[0].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("timeline.removeClip");
    restoreAndClearClipControlEditsForClip(id);
    if (audioEngine)
        audioEngine->getMixEngine().invalidateClipCache(id, "removeClip");
    g_undoManager->execute(std::make_unique<RemoveClipCommand>(id, *g_timeline), *g_timeline);
    log.done();
}

// timeline_setClipParams(clipId: number, params: object) → clipObject
// params: { pitchOffset?, pitchOffsetCents?, reversed?, stretchRatio?,
//           stretchMethod?, formantPreserve?, fadeInPercent?, fadeOutPercent? }
static SetClipParamsCommand::Params clipParamsFromClip(const Clip& clip)
{
    SetClipParamsCommand::Params p;
    p.pitchOffsetSemis = clip.pitchOffset;
    p.pitchOffsetCents = clip.pitchOffsetCents;
    p.reversed = clip.reversed;
    p.stretchRatio = clip.stretchRatio;
    p.stretchMethod = clip.stretchMethod;
    p.formantPreserve = clip.formantPreserve;
    p.velocity = clip.velocity;
    p.fadeInPercent = clip.fadeInPercent;
    p.fadeOutPercent = clip.fadeOutPercent;
    p.fadeInX1 = clip.fadeInX1;
    p.fadeInY1 = clip.fadeInY1;
    p.fadeInX2 = clip.fadeInX2;
    p.fadeInY2 = clip.fadeInY2;
    p.fadeOutX1 = clip.fadeOutX1;
    p.fadeOutY1 = clip.fadeOutY1;
    p.fadeOutX2 = clip.fadeOutX2;
    p.fadeOutY2 = clip.fadeOutY2;
    return p;
}

static JsonApi::Object trackLayoutToJs(JsonApi::Env env, const TrackLayout& layout) {
    JsonApi::Object out = JsonApi::Object::New(env);
    JsonApi::Array root = JsonApi::Array::New(env, layout.rootOrder.size());
    for (uint32_t i = 0; i < static_cast<uint32_t>(layout.rootOrder.size()); ++i) {
        const auto& item = layout.rootOrder[i];
        JsonApi::Object row = JsonApi::Object::New(env);
        row.Set("kind", JsonApi::String::New(env,
            item.kind == TrackLayoutItem::Kind::Folder ? "folder" : "track"));
        row.Set("id", JsonApi::Number::New(env, item.id));
        root.Set(i, row);
    }
    JsonApi::Array folders = JsonApi::Array::New(env, layout.folders.size());
    for (uint32_t i = 0; i < static_cast<uint32_t>(layout.folders.size()); ++i) {
        const auto& folder = layout.folders[i];
        JsonApi::Object row = JsonApi::Object::New(env);
        row.Set("id", JsonApi::Number::New(env, folder.id));
        row.Set("name", JsonApi::String::New(env, folder.name));
        row.Set("collapsed", JsonApi::Boolean::New(env, folder.collapsed));
        JsonApi::Array trackIds = JsonApi::Array::New(env, folder.trackIds.size());
        for (uint32_t j = 0; j < static_cast<uint32_t>(folder.trackIds.size()); ++j)
            trackIds.Set(j, JsonApi::Number::New(env, folder.trackIds[j]));
        row.Set("trackIds", trackIds);
        folders.Set(i, row);
    }
    out.Set("rootOrder", root);
    out.Set("folders", folders);
    return out;
}

static bool jsToTrackLayout(const JsonApi::Value& value, TrackLayout& layout) {
    if (!value.IsObject()) return false;
    JsonApi::Object object = value.As<JsonApi::Object>();
    if (!object.Has("rootOrder") || !object.Get("rootOrder").IsArray()
        || !object.Has("folders") || !object.Get("folders").IsArray())
        return false;

    TrackLayout parsed;
    JsonApi::Array root = object.Get("rootOrder").As<JsonApi::Array>();
    for (uint32_t i = 0; i < root.Length(); ++i) {
        if (!root.Get(i).IsObject()) return false;
        JsonApi::Object row = root.Get(i).As<JsonApi::Object>();
        if (!row.Has("kind") || !row.Get("kind").IsString()
            || !row.Has("id") || !row.Get("id").IsNumber())
            return false;
        const std::string kind = row.Get("kind").As<JsonApi::String>().Utf8Value();
        if (kind != "track" && kind != "folder") return false;
        parsed.rootOrder.push_back({
            kind == "folder" ? TrackLayoutItem::Kind::Folder : TrackLayoutItem::Kind::Track,
            row.Get("id").As<JsonApi::Number>().Int32Value(),
        });
    }

    JsonApi::Array folders = object.Get("folders").As<JsonApi::Array>();
    for (uint32_t i = 0; i < folders.Length(); ++i) {
        if (!folders.Get(i).IsObject()) return false;
        JsonApi::Object row = folders.Get(i).As<JsonApi::Object>();
        if (!row.Has("id") || !row.Get("id").IsNumber()
            || !row.Has("name") || !row.Get("name").IsString()
            || !row.Has("trackIds") || !row.Get("trackIds").IsArray())
            return false;
        TrackFolder folder;
        folder.id = row.Get("id").As<JsonApi::Number>().Int32Value();
        folder.name = row.Get("name").As<JsonApi::String>().Utf8Value();
        folder.collapsed = row.Has("collapsed") && row.Get("collapsed").IsBoolean()
            ? row.Get("collapsed").As<JsonApi::Boolean>().Value() : false;
        JsonApi::Array ids = row.Get("trackIds").As<JsonApi::Array>();
        for (uint32_t j = 0; j < ids.Length(); ++j) {
            if (!ids.Get(j).IsNumber()) return false;
            folder.trackIds.push_back(ids.Get(j).As<JsonApi::Number>().Int32Value());
        }
        parsed.folders.push_back(std::move(folder));
    }
    layout = std::move(parsed);
    return true;
}

static void applyClipControlPatch(Clip& clip, const JsonApi::Object& patch)
{
    bool fadeTouched = false;
    if (patch.Has("velocity") && patch.Get("velocity").IsNumber()) {
        const float value = patch.Get("velocity").As<JsonApi::Number>().FloatValue();
        clip.velocity = std::isfinite(value) ? std::max(0.0f, std::min(2.0f, value)) : 1.0f;
    }
    if (patch.Has("fadeInPercent") && patch.Get("fadeInPercent").IsNumber()) {
        fadeTouched = true;
        const float value = patch.Get("fadeInPercent").As<JsonApi::Number>().FloatValue();
        clip.fadeInPercent = std::isfinite(value) ? value : 0.0f;
    }
    if (patch.Has("fadeOutPercent") && patch.Get("fadeOutPercent").IsNumber()) {
        fadeTouched = true;
        const float value = patch.Get("fadeOutPercent").As<JsonApi::Number>().FloatValue();
        clip.fadeOutPercent = std::isfinite(value) ? value : 0.0f;
    }
    if (fadeTouched)
        normalizeClipFadePercents(clip.fadeInPercent, clip.fadeOutPercent);
}

static bool validateClipControlPatch(JsonApi::Env env, const JsonApi::Object& patch)
{
    const JsonApi::Array keys = patch.GetPropertyNames();
    for (uint32_t i = 0; i < keys.Length(); ++i) {
        const JsonApi::Value keyValue = keys.Get(i);
        if (!keyValue.IsString()) continue;
        const std::string key = keyValue.As<JsonApi::String>().Utf8Value();
        if (key != "velocity" && key != "fadeInPercent" && key != "fadeOutPercent") {
            JsonApi::TypeError::New(env, "Clip control patches accept only velocity, fadeInPercent, and fadeOutPercent")
                .ThrowAsJavaScriptException();
            return false;
        }
        if (!patch.Get(key).IsNumber()) {
            JsonApi::TypeError::New(env, "Clip control patch values must be numbers")
                .ThrowAsJavaScriptException();
            return false;
        }
    }
    return true;
}

static ClipControlEditSession* requireClipControlEdit(
    JsonApi::Env env, const JsonApi::CallbackInfo& info, const char* signature)
{
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return nullptr;
    }
    if (info.Length() < 1 || !info[0].IsNumber()) {
        JsonApi::TypeError::New(env, signature).ThrowAsJavaScriptException();
        return nullptr;
    }
    const uint32_t sessionId = info[0].As<JsonApi::Number>().Uint32Value();
    auto it = g_clipControlEdits.find(sessionId);
    if (it == g_clipControlEdits.end()) {
        JsonApi::Error::New(env, "Stale clip control edit session")
            .ThrowAsJavaScriptException();
        return nullptr;
    }
    if (!g_timeline->getClip(it->second.clipId)) {
        g_clipControlEdits.erase(it);
        JsonApi::Error::New(env, "Clip control edit target no longer exists")
            .ThrowAsJavaScriptException();
        return nullptr;
    }
    return &it->second;
}

JsonApi::Value Timeline_BeginClipControlEdit(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsNumber()) {
        JsonApi::TypeError::New(env, "timeline_beginClipControlEdit(clipId: number)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }

    const int clipId = info[0].As<JsonApi::Number>().Int32Value();
    // Only sessions on THIS clip are superseded. Sessions on other clips belong
    // to sibling members of a multi-clip drag and must survive.
    restoreAndClearClipControlEditsForClip(clipId);

    const Clip* clip = g_timeline->getClip(clipId);
    if (!clip) {
        JsonApi::Error::New(env, "Clip not found").ThrowAsJavaScriptException();
        return env.Undefined();
    }

    ClipControlEditSession edit;
    edit.sessionId = g_nextClipControlEditSessionId++;
    if (edit.sessionId == 0)
        edit.sessionId = g_nextClipControlEditSessionId++;
    edit.clipId = clipId;
    edit.initialVelocity = clip->velocity;
    edit.initialFadeInPercent = clip->fadeInPercent;
    edit.initialFadeOutPercent = clip->fadeOutPercent;

    JsonApi::Object initial = JsonApi::Object::New(env);
    initial.Set("velocity", JsonApi::Number::New(env, edit.initialVelocity));
    initial.Set("fadeInPercent", JsonApi::Number::New(env, edit.initialFadeInPercent));
    initial.Set("fadeOutPercent", JsonApi::Number::New(env, edit.initialFadeOutPercent));
    JsonApi::Object result = JsonApi::Object::New(env);
    result.Set("sessionId", JsonApi::Number::New(env, edit.sessionId));
    result.Set("initial", initial);
    g_clipControlEdits[edit.sessionId] = edit;
    return result;
}

JsonApi::Value Timeline_PreviewClipControlEdit(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    ClipControlEditSession* edit = requireClipControlEdit(
        env, info, "timeline_previewClipControlEdit(sessionId: number, patch: object)");
    if (!edit) return env.Undefined();
    if (info.Length() < 2 || !info[1].IsObject()) {
        JsonApi::TypeError::New(
            env, "timeline_previewClipControlEdit(sessionId: number, patch: object)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    Clip* clip = g_timeline->getClipMutable(edit->clipId);
    JsonApi::Object patch = info[1].As<JsonApi::Object>();
    if (!validateClipControlPatch(env, patch)) return env.Undefined();
    applyClipControlPatch(*clip, patch);
    g_previewDirty.store(true);
    return clipToJs(env, *clip);
}

JsonApi::Value Timeline_CancelClipControlEdit(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    ClipControlEditSession* edit = requireClipControlEdit(
        env, info, "timeline_cancelClipControlEdit(sessionId: number)");
    if (!edit) return env.Undefined();
    const int clipId = edit->clipId;
    const uint32_t sessionId = edit->sessionId;
    restoreClipControlEditSession(*edit);
    g_clipControlEdits.erase(sessionId);   // invalidates `edit`
    g_previewDirty.store(true);
    const Clip* clip = g_timeline->getClip(clipId);
    return clip ? clipToJs(env, *clip) : env.Undefined();
}

JsonApi::Value Timeline_CommitClipControlEdit(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    ClipControlEditSession* edit = requireClipControlEdit(
        env, info, "timeline_commitClipControlEdit(sessionId: number, finalPatch: object)");
    if (!edit) return env.Undefined();
    if (info.Length() < 2 || !info[1].IsObject()) {
        JsonApi::TypeError::New(
            env, "timeline_commitClipControlEdit(sessionId: number, finalPatch: object)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }

    Clip* preview = g_timeline->getClipMutable(edit->clipId);
    JsonApi::Object finalPatch = info[1].As<JsonApi::Object>();
    if (!validateClipControlPatch(env, finalPatch)) return env.Undefined();
    applyClipControlPatch(*preview, finalPatch);
    const int clipId = edit->clipId;
    const float finalVelocity = preview->velocity;
    const float finalFadeInPercent = preview->fadeInPercent;
    const float finalFadeOutPercent = preview->fadeOutPercent;
    const bool changed =
        std::abs(finalVelocity - edit->initialVelocity) > 1.0e-6f ||
        std::abs(finalFadeInPercent - edit->initialFadeInPercent) > 1.0e-5f ||
        std::abs(finalFadeOutPercent - edit->initialFadeOutPercent) > 1.0e-5f;

    // Roll THIS clip back to its pre-drag values so the undo command below
    // records a real before/after pair, then drop only this session — sibling
    // sessions from the same multi-clip drag are still waiting to commit.
    const uint32_t sessionId = edit->sessionId;
    restoreClipControlEditSession(*edit);
    g_clipControlEdits.erase(sessionId);   // invalidates `edit`

    if (changed) {
        const Clip* baseline = g_timeline->getClip(clipId);
        if (!baseline) {
            JsonApi::Error::New(env, "Clip no longer exists").ThrowAsJavaScriptException();
            return env.Undefined();
        }
        SetClipParamsCommand::Params params = clipParamsFromClip(*baseline);
        params.velocity = finalVelocity;
        params.fadeInPercent = finalFadeInPercent;
        params.fadeOutPercent = finalFadeOutPercent;
        g_undoManager->execute(
            std::make_unique<SetClipParamsCommand>(clipId, params, *g_timeline),
            *g_timeline);
    }
    g_previewDirty.store(true);
    const Clip* committed = g_timeline->getClip(clipId);
    return committed ? clipToJs(env, *committed) : env.Undefined();
}

JsonApi::Value Timeline_SetClipParams(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsObject()) {
        JsonApi::TypeError::New(env, "timeline_setClipParams(clipId: number, params: object)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }

    int clipId = info[0].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("timeline.setClipParams");

    // A normal parameter command supersedes any in-flight transient preview.
    restoreAndClearClipControlEdit();

    const Clip* existing = g_timeline->getClip(clipId);
    if (!existing) {
        JsonApi::Error::New(env, "Clip not found").ThrowAsJavaScriptException();
        return env.Undefined();
    }

    JsonApi::Object o = info[1].As<JsonApi::Object>();
    SetClipParamsCommand::Params p;
    p.pitchOffsetSemis = existing->pitchOffset;
    p.pitchOffsetCents = existing->pitchOffsetCents;
    p.reversed         = existing->reversed;
    p.stretchRatio     = existing->stretchRatio;
    p.stretchMethod    = existing->stretchMethod;
    p.formantPreserve  = existing->formantPreserve;
    p.velocity         = existing->velocity;
    p.fadeInPercent    = existing->fadeInPercent;
    p.fadeOutPercent   = existing->fadeOutPercent;
    p.fadeInX1         = existing->fadeInX1;
    p.fadeInY1         = existing->fadeInY1;
    p.fadeInX2         = existing->fadeInX2;
    p.fadeInY2         = existing->fadeInY2;
    p.fadeOutX1        = existing->fadeOutX1;
    p.fadeOutY1        = existing->fadeOutY1;
    p.fadeOutX2        = existing->fadeOutX2;
    p.fadeOutY2        = existing->fadeOutY2;

    if (o.Has("pitchOffset") && o.Get("pitchOffset").IsNumber())
        p.pitchOffsetSemis = o.Get("pitchOffset").As<JsonApi::Number>().Int32Value();
    if (o.Has("pitchOffsetCents") && o.Get("pitchOffsetCents").IsNumber()) {
        int c = o.Get("pitchOffsetCents").As<JsonApi::Number>().Int32Value();
        p.pitchOffsetCents = std::max(-99, std::min(99, c));
    }
    if (o.Has("reversed") && o.Get("reversed").IsBoolean())
        p.reversed = o.Get("reversed").As<JsonApi::Boolean>().Value();
    if (o.Has("stretchRatio") && o.Get("stretchRatio").IsNumber()) {
        double r = o.Get("stretchRatio").As<JsonApi::Number>().DoubleValue();
        p.stretchRatio = (r <= 0.0) ? 1.0 : r;
    }
    if (o.Has("stretchMethod") && o.Get("stretchMethod").IsNumber()) {
        int sm = o.Get("stretchMethod").As<JsonApi::Number>().Int32Value();
        p.stretchMethod = static_cast<StretchMethod>(
            (sm >= 0 && sm <= 5) ? sm : 0 /*Global*/);
    }
    if (o.Has("formantPreserve") && o.Get("formantPreserve").IsBoolean())
        p.formantPreserve = o.Get("formantPreserve").As<JsonApi::Boolean>().Value();
    if (o.Has("velocity") && o.Get("velocity").IsNumber())
        p.velocity = o.Get("velocity").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeInPercent") && o.Get("fadeInPercent").IsNumber())
        p.fadeInPercent = o.Get("fadeInPercent").As<JsonApi::Number>().FloatValue();
    else if (o.Has("fadeInTicks") && o.Get("fadeInTicks").IsNumber())
        p.fadeInPercent = legacyFadeTicksToPercent(
            o.Get("fadeInTicks").As<JsonApi::Number>().FloatValue(), existing->duration.ticks);
    if (o.Has("fadeOutPercent") && o.Get("fadeOutPercent").IsNumber())
        p.fadeOutPercent = o.Get("fadeOutPercent").As<JsonApi::Number>().FloatValue();
    else if (o.Has("fadeOutTicks") && o.Get("fadeOutTicks").IsNumber())
        p.fadeOutPercent = legacyFadeTicksToPercent(
            o.Get("fadeOutTicks").As<JsonApi::Number>().FloatValue(), existing->duration.ticks);
    normalizeClipFadePercents(p.fadeInPercent, p.fadeOutPercent);
    if (o.Has("fadeInX1") && o.Get("fadeInX1").IsNumber())
        p.fadeInX1 = o.Get("fadeInX1").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeInY1") && o.Get("fadeInY1").IsNumber())
        p.fadeInY1 = o.Get("fadeInY1").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeInX2") && o.Get("fadeInX2").IsNumber())
        p.fadeInX2 = o.Get("fadeInX2").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeInY2") && o.Get("fadeInY2").IsNumber())
        p.fadeInY2 = o.Get("fadeInY2").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeOutX1") && o.Get("fadeOutX1").IsNumber())
        p.fadeOutX1 = o.Get("fadeOutX1").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeOutY1") && o.Get("fadeOutY1").IsNumber())
        p.fadeOutY1 = o.Get("fadeOutY1").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeOutX2") && o.Get("fadeOutX2").IsNumber())
        p.fadeOutX2 = o.Get("fadeOutX2").As<JsonApi::Number>().FloatValue();
    if (o.Has("fadeOutY2") && o.Get("fadeOutY2").IsNumber())
        p.fadeOutY2 = o.Get("fadeOutY2").As<JsonApi::Number>().FloatValue();

    // Only invalidate render cache for pitch/stretch/reverse changes (not volume/fade)
    const bool needsCacheInvalidation =
        p.pitchOffsetSemis != existing->pitchOffset ||
        p.pitchOffsetCents != existing->pitchOffsetCents ||
        p.reversed         != existing->reversed ||
        std::abs(p.stretchRatio - existing->stretchRatio) > 1e-9 ||
        p.stretchMethod    != existing->stretchMethod ||
        p.formantPreserve  != existing->formantPreserve;

    g_undoManager->execute(
        std::make_unique<SetClipParamsCommand>(clipId, p, *g_timeline),
        *g_timeline);

    if (audioEngine && needsCacheInvalidation)
        audioEngine->getMixEngine().invalidateClipCache(clipId, "setClipParams");

    const Clip* updated = g_timeline->getClip(clipId);
    if (!updated) return env.Undefined();
    log.done(std::to_string(clipId));
    return clipToJs(env, *updated);
}

// timeline_setClipModulation(clipId: number, modulation: object) → clipObject
// Partial-update: missing nested objects/fields preserve existing values.
// Unknown fields are ignored. Invalid enum strings fall back to the existing
// value. Modulation edits refresh preview state, but do not invalidate
// ClipRenderCache because vibrato/scratch now run after the processed clip
// buffer.
JsonApi::Value Timeline_SetClipModulation(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsObject()) {
        JsonApi::TypeError::New(env, "timeline_setClipModulation(clipId: number, modulation: object)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }

    int clipId = info[0].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("timeline.setClipModulation");

    const Clip* existing = g_timeline->getClip(clipId);
    if (!existing) {
        JsonApi::Error::New(env, "Clip not found").ThrowAsJavaScriptException();
        return env.Undefined();
    }

    JsonApi::Object o = info[1].As<JsonApi::Object>();
    ClipModulation merged = jsToClipModulation(o, existing->modulation);

    g_undoManager->execute(
        std::make_unique<SetClipModulationCommand>(clipId, merged, *g_timeline),
        *g_timeline);

    // ClipRenderCache stores only pre-modulation clip processing
    // (source/trim/stretch/static pitch/reverse/formant). Vibrato and Scratch
    // run after that buffer, so modulation edits refresh preview state without
    // evicting or rebuilding the stretch cache.
    g_previewDirty.store(true);

    const Clip* updated = g_timeline->getClip(clipId);
    if (!updated) return env.Undefined();
    log.done(std::to_string(clipId));
    return clipToJs(env, *updated);
}

// timeline_setClipModulationBatch([{ clipId, modulation }, ...]) → Clip[]
// The batched form of timeline_setClipModulation: N clips, ONE undo entry, ONE
// round trip. Each `modulation` is a PARTIAL patch merged onto that clip's own
// existing descriptor — identical semantics to the single-clip call, so the
// caller can send just `{ video: { vibratoSwirlEnabled: true, swirlAmount } }`
// without having to echo back the vibrato/scratch blocks it isn't touching.
//
// Written for "apply my default video companion FX to every video clip that
// doesn't have it on": that walks the whole project, and a serial loop of
// setClipModulation pushed one undo entry per clip (UndoManager caps at 100, so
// a large project silently lost its history and Ctrl+Z reverted one clip).
// Unknown clip ids are skipped, not an error — the renderer's clip list can be
// a frame stale relative to the engine.
JsonApi::Value Timeline_SetClipModulationBatch(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsArray()) {
        JsonApi::TypeError::New(env,
            "timeline_setClipModulationBatch(edits: Array<{clipId, modulation}>)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    BridgeCallLog log("timeline.setClipModulationBatch");

    JsonApi::Array arr = info[0].As<JsonApi::Array>();
    std::vector<SetClipModulationBatchCommand::Edit> edits;
    edits.reserve(arr.Length());
    for (uint32_t i = 0; i < arr.Length(); ++i) {
        if (!arr.Get(i).IsObject()) continue;
        JsonApi::Object o = arr.Get(i).As<JsonApi::Object>();
        if (!o.Has("clipId") || !o.Get("clipId").IsNumber()) continue;
        if (!o.Has("modulation") || !o.Get("modulation").IsObject()) continue;

        int clipId = o.Get("clipId").As<JsonApi::Number>().Int32Value();
        const Clip* existing = g_timeline->getClip(clipId);
        if (!existing) continue;

        SetClipModulationBatchCommand::Edit e;
        e.clipId     = clipId;
        e.modulation = jsToClipModulation(o.Get("modulation").As<JsonApi::Object>(),
                                          existing->modulation);
        edits.push_back(std::move(e));
    }
    if (edits.empty()) { log.done("0"); return JsonApi::Array::New(env, 0); }

    auto cmd = std::make_unique<SetClipModulationBatchCommand>(std::move(edits), *g_timeline);
    SetClipModulationBatchCommand* cmdPtr = cmd.get();
    g_undoManager->execute(std::move(cmd), *g_timeline);

    // Same reasoning as timeline_setClipModulation: vibrato/scratch run after
    // the ClipRenderCache buffer, so this refreshes preview state without
    // evicting the stretch cache.
    g_previewDirty.store(true);

    const auto& ids = cmdPtr->getEditedIds();
    log.done(std::to_string(ids.size()));
    return clipsByIdToJs(env, ids);
}


// timeline_moveClip(id, trackId, posTicks) -> clipObject | undefined
// trackId is the destination Clip track (enables cross-track clip moves);
// Timeline::moveClip rejects a Pattern-track destination.
//
// Returns the moved clip's post-state (undefined if the id no longer resolves)
// so the caller can splice one clip into its list. Every single-clip mutation
// below answers the same way, for the same reason as the batch ops: a bare void
// forced the renderer to refetch the WHOLE project to learn one clip's new
// position.
JsonApi::Value Timeline_MoveClip(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 3 || !info[0].IsNumber() || !info[1].IsNumber() || !info[2].IsNumber()) {
        JsonApi::TypeError::New(env, "timeline_moveClip(id: number, trackId: number, posTicks: number)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    int     id       = info[0].As<JsonApi::Number>().Int32Value();
    int     trackId  = info[1].As<JsonApi::Number>().Int32Value();
    int64_t posTicks = static_cast<int64_t>(info[2].As<JsonApi::Number>().DoubleValue());
    BridgeCallLog log("timeline.moveClip");

    TickTime newPos; newPos.ticks = posTicks;
    g_undoManager->execute(std::make_unique<MoveClipCommand>(id, trackId, newPos, *g_timeline), *g_timeline);
    if (audioEngine) audioEngine->getMixEngine().invalidateClipCache(id, "moveClip");
    log.done();
    const Clip* moved = g_timeline->getClip(id);
    return moved ? clipToJs(env, *moved) : env.Undefined();
}

