// timeline_addNotesBatch(patternId, notes[])
// notes = [{ positionTicks, durationTicks, pitch, velocity, isSlide,
//            slideCurveCx?, slideCurveCy? }, ...]
// Inserts N notes into an existing pattern as a single undoable command.
// Returns the array of real note IDs the pattern assigned (one per inserted
// note, in insertion order). Invalid note entries are skipped defensively.
JsonApi::Value Timeline_AddNotesBatch(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsArray()) {
        JsonApi::TypeError::New(env, "timeline_addNotesBatch(patternId: number, notes: array)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    int patternId = info[0].As<JsonApi::Number>().Int32Value();
    JsonApi::Array arr = info[1].As<JsonApi::Array>();

    std::vector<PatternNote> notes;
    notes.reserve(arr.Length());
    for (uint32_t i = 0; i < arr.Length(); ++i) {
        JsonApi::Value v = arr.Get(i);
        if (!v.IsObject()) continue;
        JsonApi::Object o = v.As<JsonApi::Object>();
        // Reject malformed entries: require the minimum geometry fields.
        if (!o.Has("positionTicks") || !o.Has("durationTicks") || !o.Has("pitch"))
            continue;
        PatternNote n = jsToPatternNote(o);   // id stays 0 → assigned by the command
        n.id = 0;
        notes.push_back(n);
    }

    BridgeCallLog log("timeline.addNotesBatch");

    auto cmd = std::make_unique<AddNotesBatchCommand>(patternId, std::move(notes));
    AddNotesBatchCommand* cmdPtr = cmd.get();
    g_undoManager->execute(std::move(cmd), *g_timeline);

    // Return the real IDs the pattern assigned during execute().
    const std::vector<int>& ids = cmdPtr->getAssignedIds();
    JsonApi::Array out = JsonApi::Array::New(env, ids.size());
    for (size_t i = 0; i < ids.size(); ++i)
        out.Set(static_cast<uint32_t>(i), JsonApi::Number::New(env, ids[i]));
    log.done(std::to_string(ids.size()) + " note(s)");
    return out;
}

// timeline_editPatternNotes(patternId, notes[])
// notes = the pattern's COMPLETE note list after the edit. Entries with an
// `id` > 0 keep it; entries without one are new notes. One undo entry.
// Returns the resulting note list (with every id filled in).
JsonApi::Value Timeline_EditPatternNotes(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsArray()) {
        JsonApi::TypeError::New(env, "timeline_editPatternNotes(patternId: number, notes: array)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    int patternId = info[0].As<JsonApi::Number>().Int32Value();
    if (!g_timeline->getPattern(patternId)) return env.Null();
    JsonApi::Array arr = info[1].As<JsonApi::Array>();

    std::vector<PatternNote> notes;
    notes.reserve(arr.Length());
    for (uint32_t i = 0; i < arr.Length(); ++i) {
        JsonApi::Value v = arr.Get(i);
        if (!v.IsObject()) continue;
        JsonApi::Object o = v.As<JsonApi::Object>();
        if (!o.Has("positionTicks") || !o.Has("durationTicks") || !o.Has("pitch"))
            continue;
        PatternNote n = jsToPatternNote(o);
        n.id = (o.Has("id") && o.Get("id").IsNumber())
            ? o.Get("id").As<JsonApi::Number>().Int32Value() : 0;
        if (n.position.ticks < 0) n.position.ticks = 0;
        if (n.duration.ticks < 1) n.duration.ticks = 1;
        if (n.pitch < 0) n.pitch = 0;
        if (n.pitch > 127) n.pitch = 127;
        notes.push_back(n);
    }

    BridgeCallLog log("timeline.editPatternNotes");
    auto cmd = std::make_unique<EditPatternNotesCommand>(patternId, std::move(notes), *g_timeline);
    EditPatternNotesCommand* cmdPtr = cmd.get();
    g_undoManager->execute(std::move(cmd), *g_timeline);

    const std::vector<PatternNote>& after = cmdPtr->getAfter();
    JsonApi::Array out = JsonApi::Array::New(env, after.size());
    for (size_t i = 0; i < after.size(); ++i)
        out.Set(static_cast<uint32_t>(i), patternNoteToJs(env, after[i]));
    log.done(std::to_string(after.size()) + " note(s)");
    return out;
}

// fsc_parse(filePath)
// Pure read-only FL Studio Score (.fsc) parse. Wraps FscScoreParser::parseFile.
// Does NOT touch Timeline / Pattern / undo / project state. Returns neutral
// note data converted to Xleth's 960 PPQ, preserving droppedCount and the
// source (FL) timing for diagnostics.
JsonApi::Value Fsc_Parse(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (info.Length() < 1 || !info[0].IsString()) {
        JsonApi::TypeError::New(env, "fsc_parse(filePath: string)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    const std::string filePath = info[0].As<JsonApi::String>().Utf8Value();

    BridgeCallLog log("fsc.parse");
    const xleth::import::FscParseResult res =
        xleth::import::FscScoreParser::parseFile(filePath);

    JsonApi::Object out = JsonApi::Object::New(env);
    out.Set("ok",           JsonApi::Boolean::New(env, res.ok));
    if (!res.error.empty())
        out.Set("error",    JsonApi::String::New(env, res.error));
    out.Set("sourcePpq",    JsonApi::Number::New(env, res.sourcePpq));
    out.Set("xlethPpq",     JsonApi::Number::New(env, res.xlethPpq));
    out.Set("droppedCount", JsonApi::Number::New(env, res.droppedCount));

    JsonApi::Array notes = JsonApi::Array::New(env, res.notes.size());
    for (size_t i = 0; i < res.notes.size(); ++i) {
        const xleth::import::ImportedFscNote& n = res.notes[i];
        JsonApi::Object jn = JsonApi::Object::New(env);
        // Converted Xleth 960-PPQ timing.
        jn.Set("positionTicks",       JsonApi::Number::New(env, static_cast<double>(n.xlethStartTick)));
        jn.Set("lengthTicks",         JsonApi::Number::New(env, static_cast<double>(n.xlethLengthTick)));
        jn.Set("pitch",               JsonApi::Number::New(env, n.key));
        jn.Set("velocity",            JsonApi::Number::New(env, n.velocity));
        jn.Set("isSlide",             JsonApi::Boolean::New(env, n.isSlide));
        jn.Set("markerByte",          JsonApi::Number::New(env, n.markerByte));
        // Source (FL) timing + raw fields for diagnostics.
        jn.Set("sourcePositionTicks", JsonApi::Number::New(env, static_cast<double>(n.sourcePositionTicks)));
        jn.Set("sourceLengthTicks",   JsonApi::Number::New(env, static_cast<double>(n.sourceLengthTicks)));
        jn.Set("flags",               JsonApi::Number::New(env, n.flags));
        jn.Set("group",               JsonApi::Number::New(env, n.group));
        notes.Set(static_cast<uint32_t>(i), jn);
    }
    out.Set("notes", notes);

    log.done(res.ok ? (std::to_string(res.notes.size()) + " note(s)") : res.error);
    return out;
}

// timeline_quantizeClipsBatch(specs[])
// specs = [{ id, isPatternBlock, newStartTicks, newEndTicks, newOffsetTicks,
//            newStretchRatio }, ...]
// The UI pre-computes the new geometry; this handler snapshots the current
// state for undo and applies all changes in one atomic command.
JsonApi::Value Timeline_QuantizeClipsBatch(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !g_undoManager) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsArray()) {
        JsonApi::TypeError::New(env, "timeline_quantizeClipsBatch(specs: array)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    JsonApi::Array arr = info[0].As<JsonApi::Array>();
    std::vector<QuantizeClipsBatchCommand::QuantizeClipSnapshot> snaps;
    snaps.reserve(arr.Length());
    for (uint32_t i = 0; i < arr.Length(); ++i) {
        JsonApi::Value v = arr.Get(i);
        if (!v.IsObject()) continue;
        JsonApi::Object o = v.As<JsonApi::Object>();
        if (!o.Has("id") || !o.Has("isPatternBlock")
            || !o.Has("newStartTicks") || !o.Has("newEndTicks")
            || !o.Has("newOffsetTicks")) continue;

        QuantizeClipsBatchCommand::QuantizeClipSnapshot s;
        s.id             = o.Get("id").As<JsonApi::Number>().Int32Value();
        s.isPatternBlock = o.Get("isPatternBlock").As<JsonApi::Boolean>().Value();
        s.newStart       = static_cast<int64_t>(o.Get("newStartTicks").As<JsonApi::Number>().DoubleValue());
        s.newEnd         = static_cast<int64_t>(o.Get("newEndTicks").As<JsonApi::Number>().DoubleValue());
        s.newOffset      = static_cast<int64_t>(o.Get("newOffsetTicks").As<JsonApi::Number>().DoubleValue());
        s.newStretch     = o.Has("newStretchRatio")
            ? o.Get("newStretchRatio").As<JsonApi::Number>().DoubleValue()
            : 1.0;

        // Capture old state from the timeline.
        if (s.isPatternBlock) {
            const PatternBlock* pb = g_timeline->getPatternBlock(s.id);
            if (!pb) {
                std::cerr << "[Quantize] patternBlock id=" << s.id << " not found, skipping\n";
                continue;
            }
            s.oldStart   = pb->position.ticks;
            s.oldEnd     = pb->position.ticks + pb->duration.ticks;
            s.oldOffset  = pb->offset.ticks;
            s.oldStretch = 1.0;
            s.newStretch = 1.0; // ignored for pattern blocks
        } else {
            const Clip* c = g_timeline->getClip(s.id);
            if (!c) {
                std::cerr << "[Quantize] clip id=" << s.id << " not found, skipping\n";
                continue;
            }
            s.oldStart   = c->position.ticks;
            s.oldEnd     = c->position.ticks + c->duration.ticks;
            s.oldOffset  = c->regionOffset.ticks;
            s.oldStretch = c->stretchRatio;
        }
        snaps.push_back(s);
    }
    if (snaps.empty()) return JsonApi::Array::New(env, 0);
    BridgeCallLog log("timeline.quantizeClipsBatch");
    // Post-state of the CLIP entries only (pattern blocks have their own list
    // renderer-side and are refetched with it); the caller reconciles from this
    // instead of refetching every clip in the project.
    std::vector<int> clipIds;
    clipIds.reserve(snaps.size());
    for (const auto& s : snaps)
        if (!s.isPatternBlock) clipIds.push_back(s.id);

    g_undoManager->execute(
        std::make_unique<QuantizeClipsBatchCommand>(std::move(snaps)),
        *g_timeline);
    log.done();
    return clipsByIdToJs(env, clipIds);
}

