static PingPongSettings jsToPingPongSettings(JsonApi::Object o) {
    PingPongSettings p;
    auto getF = [&](const char* k, float& v) {
        if (o.Has(k) && o.Get(k).IsNumber()) v = o.Get(k).As<JsonApi::Number>().FloatValue();
    };
    auto getB = [&](const char* k, bool& v) {
        if (o.Has(k) && o.Get(k).IsBoolean()) v = o.Get(k).As<JsonApi::Boolean>().Value();
    };
    auto getI = [&](const char* k, int& v) {
        if (o.Has(k) && o.Get(k).IsNumber()) v = o.Get(k).As<JsonApi::Number>().Int32Value();
    };
    getB("enabled",         p.enabled);
    getF("regionStartPct",  p.regionStartPct);
    getF("regionEndPct",    p.regionEndPct);
    getI("crossfadeFrames", p.crossfadeFrames);
    getF("reverseSpeed",    p.reverseSpeed);
    getI("maxLoops",        p.maxLoops);
    return p;
}

