static SlideTVSettings jsToSlideTVSettings(JsonApi::Object o) {
    SlideTVSettings t;
    auto getF = [&](const char* k, float& v) {
        if (o.Has(k) && o.Get(k).IsNumber()) v = o.Get(k).As<JsonApi::Number>().FloatValue();
    };
    getF("intensity",  t.intensity);
    getF("rollSpeed",  t.rollSpeed);
    getF("scanlines",  t.scanlines);
    getF("chroma",     t.chroma);
    getF("noise",      t.noise);
    getF("jitter",     t.jitter);
    getF("colorBleed", t.colorBleed);
    return t;
}

static SlideNoteEffectSettings jsToSlideNoteEffectSettings(JsonApi::Object o) {
    SlideNoteEffectSettings s;
    if (o.Has("type") && o.Get("type").IsNumber()) {
        int t = o.Get("type").As<JsonApi::Number>().Int32Value();
        if (t < 0) t = 0;
        if (t > 3) t = 3;
        s.type = static_cast<SlideNoteEffectSettings::EffectType>(t);
    }
    if (o.Has("durationMode") && o.Get("durationMode").IsNumber()) {
        int d = o.Get("durationMode").As<JsonApi::Number>().Int32Value();
        if (d < 0) d = 0;
        if (d > 1) d = 1;
        s.durationMode = static_cast<SlideNoteEffectSettings::DurationMode>(d);
    }
    if (o.Has("fixedDurationMs") && o.Get("fixedDurationMs").IsNumber())
        s.fixedDurationMs = o.Get("fixedDurationMs").As<JsonApi::Number>().FloatValue();

    // Visual return policy (added with the configurable-return system).
    if (o.Has("returnStyle") && o.Get("returnStyle").IsNumber()) {
        int r = o.Get("returnStyle").As<JsonApi::Number>().Int32Value();
        if (r < 0) r = 0; if (r > 1) r = 1;
        s.returnStyle = static_cast<SlideNoteEffectSettings::ReturnStyle>(r);
    }
    if (o.Has("returnTrigger") && o.Get("returnTrigger").IsNumber()) {
        int r = o.Get("returnTrigger").As<JsonApi::Number>().Int32Value();
        if (r < 0) r = 0; if (r > 1) r = 1;
        s.returnTrigger = static_cast<SlideNoteEffectSettings::ReturnTrigger>(r);
    }
    if (o.Has("returnDurationMs") && o.Get("returnDurationMs").IsNumber())
        s.returnDurationMs = o.Get("returnDurationMs").As<JsonApi::Number>().FloatValue();

    // New nested shape — reuse the existing Visual FX converters.
    if (o.Has("bounce") && o.Get("bounce").IsObject()) {
        s.bounce = jsToBounceSettings(o.Get("bounce").As<JsonApi::Object>());
    } else {
        // Legacy migration: flat slideBounce* keys
        if (o.Has("slideBounceDistance") && o.Get("slideBounceDistance").IsNumber())
            s.bounce.distance = o.Get("slideBounceDistance").As<JsonApi::Number>().FloatValue();
        if (o.Has("slideBounceDirDeg") && o.Get("slideBounceDirDeg").IsNumber())
            s.bounce.directionDeg = o.Get("slideBounceDirDeg").As<JsonApi::Number>().FloatValue();
    }

    if (o.Has("zoomPanRot") && o.Get("zoomPanRot").IsObject()) {
        JsonApi::Object zo = o.Get("zoomPanRot").As<JsonApi::Object>();
        s.zoomPanRot = jsToZoomPanRotSettings(zo);
        // Keyframe curves, when the slide's own ZPR editor sent them. Unlike
        // the track-level path there is no separate tracks RPC here: the slide
        // config is written whole, so the curves ride along with it.
        //
        // authored is DERIVED, not taken on trust — exactly the rule
        // loadOrMigrateZprTracks uses. A payload whose curves are just what
        // the scalars would produce stays non-authored, so scalar edits keep
        // working; only genuinely hand-authored keyframes latch the flag and
        // become un-flattenable.
        if (zo.Has("tracks") && zo.Get("tracks").IsObject()) {
            ZprTracks incoming = zprTracksFromJson(valueToJson(zo.Get("tracks")));
            const bool anyKeys =
                !incoming.panX.keys.empty() || !incoming.panY.keys.empty()
                || !incoming.zoomLog2.keys.empty() || !incoming.rotationDeg.keys.empty();
            if (anyKeys) {
                ZprTracks derived;
                buildZprTracks(derived, s.zoomPanRot);
                incoming.authored = !zprTracksEquivalent(incoming, derived);
                s.zoomPanRot.tracks = std::move(incoming);
            }
        }
    } else {
        // Legacy migration: literal value preserved, semantics shift from
        // delta to absolute. Default-valued projects behave identically.
        s.zoomPanRot.startZoom     = 1.0f;
        s.zoomPanRot.startPanX     = 0.0f;
        s.zoomPanRot.startPanY     = 0.0f;
        s.zoomPanRot.startRotation = 0.0f;
        if (o.Has("slideZoomDelta") && o.Get("slideZoomDelta").IsNumber())
            s.zoomPanRot.targetZoom = o.Get("slideZoomDelta").As<JsonApi::Number>().FloatValue();
        if (o.Has("slidePanXDelta") && o.Get("slidePanXDelta").IsNumber())
            s.zoomPanRot.targetPanX = o.Get("slidePanXDelta").As<JsonApi::Number>().FloatValue();
        if (o.Has("slidePanYDelta") && o.Get("slidePanYDelta").IsNumber())
            s.zoomPanRot.targetPanY = o.Get("slidePanYDelta").As<JsonApi::Number>().FloatValue();
        if (o.Has("slideRotationDelta") && o.Get("slideRotationDelta").IsNumber())
            s.zoomPanRot.targetRotation = o.Get("slideRotationDelta").As<JsonApi::Number>().FloatValue();
    }

    if (o.Has("tv") && o.Get("tv").IsObject()) {
        s.tv = jsToSlideTVSettings(o.Get("tv").As<JsonApi::Object>());
    } else if (o.Has("slideTVIntensity") && o.Get("slideTVIntensity").IsNumber()) {
        s.tv.intensity = o.Get("slideTVIntensity").As<JsonApi::Number>().FloatValue();
    }
    return s;
}

static NoteFadeSettings jsToNoteFadeSettings(JsonApi::Object o) {
    NoteFadeSettings s;
    if (o.Has("enabled") && o.Get("enabled").IsBoolean())
        s.enabled = o.Get("enabled").As<JsonApi::Boolean>().Value();

    // Every side field is optional and falls back to the struct default, so the
    // UI can send a partial patch merged onto what it already read back without
    // the engine reinterpreting an absent key as zero.
    auto readSide = [](JsonApi::Object so, NoteFadeSettings::Side& side) {
        if (so.Has("mode") && so.Get("mode").IsNumber()) {
            int m = so.Get("mode").As<JsonApi::Number>().Int32Value();
            if (m < 0) m = 0;
            if (m > 2) m = 2;
            side.mode = static_cast<NoteFadeSettings::LengthMode>(m);
        }
        if (so.Has("percent") && so.Get("percent").IsNumber())
            side.percent = so.Get("percent").As<JsonApi::Number>().FloatValue();
        if (so.Has("divisionDenominator") && so.Get("divisionDenominator").IsNumber())
            side.divisionDenominator = so.Get("divisionDenominator").As<JsonApi::Number>().Int32Value();
        if (so.Has("ms") && so.Get("ms").IsNumber())
            side.ms = so.Get("ms").As<JsonApi::Number>().FloatValue();
        if (so.Has("curve") && so.Get("curve").IsNumber()) {
            int c = so.Get("curve").As<JsonApi::Number>().Int32Value();
            if (c < 0) c = 0;
            if (c > 3) c = 3;
            side.curve = static_cast<NoteFadeSettings::Curve>(c);
        }
    };
    if (o.Has("fadeIn") && o.Get("fadeIn").IsObject())
        readSide(o.Get("fadeIn").As<JsonApi::Object>(), s.fadeIn);
    if (o.Has("fadeOut") && o.Get("fadeOut").IsObject())
        readSide(o.Get("fadeOut").As<JsonApi::Object>(), s.fadeOut);
    return s;
}

