// audio_getAllPeaks() → { master: {peakL, peakR}, tracks: { [trackId]: {peakL, peakR} } }
// Single batched call for mixer UI — avoids N+1 IPC round-trips per poll cycle.
JsonApi::Value Audio_GetAllPeaks(const JsonApi::CallbackInfo& info)
{
    IPC_TIME_START;
    JsonApi::Env env = info.Env();
    if (!isInitialised()) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    auto& mix = audioEngine->getMixEngine();
    JsonApi::Object result = JsonApi::Object::New(env);

    // Master peaks
    JsonApi::Object master = JsonApi::Object::New(env);
    master.Set("peakL", JsonApi::Number::New(env, mix.getMasterPeakL()));
    master.Set("peakR", JsonApi::Number::New(env, mix.getMasterPeakR()));
    result.Set("master", master);

    // Per-track peaks — iterate active tracks from timeline
    auto allTracks = g_timeline->getAllTracks();
    JsonApi::Object tracks = JsonApi::Object::New(env);
    for (size_t i = 0; i < allTracks.size(); ++i) {
        const auto& t = *allTracks[i];
        JsonApi::Object tp = JsonApi::Object::New(env);
        tp.Set("peakL", JsonApi::Number::New(env, mix.getTrackPeakL(t.id)));
        tp.Set("peakR", JsonApi::Number::New(env, mix.getTrackPeakR(t.id)));
        tracks.Set(static_cast<uint32_t>(t.id), tp);
    }
    result.Set("tracks", tracks);
    IPC_TIME_END("audio_getAllPeaks");
    return result;
}

