// getAudioPerformanceTelemetry() -> plain object
JsonApi::Value Audio_GetAudioPerformanceTelemetry(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised()) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return JsonApi::Object::New(env);
    }

    const auto snapshot = audioEngine->getAudioPerformanceTelemetrySnapshot();
    const auto presentationDiag =
        audioEngine->getLivePresentationLatencyDiagnostics();
    Transport& transport = audioEngine->getTransport();

    const double sampleRate = snapshot.lastSampleRate > 0.0
        ? snapshot.lastSampleRate
        : audioEngine->getSampleRate();
    const int blockSize = snapshot.lastBlockSize > 0
        ? snapshot.lastBlockSize
        : audioEngine->getBufferSize();
    const double callbackDeadlineUs = snapshot.lastDeadlineMs * 1000.0;
    const int64_t rawPositionSamples = transport.getPositionSamples();
    const int64_t presentationPositionSamples =
        audioEngine->getLivePresentationPositionSamples();

    JsonApi::Object obj = JsonApi::Object::New(env);
    obj.Set("enabled", JsonApi::Boolean::New(env, snapshot.enabled));
    obj.Set("sampleRate", JsonApi::Number::New(env, sampleRate));
    obj.Set("blockSize", JsonApi::Number::New(env, blockSize));
    obj.Set("callbackDeadlineUs", JsonApi::Number::New(env, callbackDeadlineUs));

    obj.Set("callback", MakeMetricObject(
        env,
        snapshot.audioCallbackCount,
        snapshot.avgAudioCallbackMs,
        snapshot.p50AudioCallbackMs,
        snapshot.p95AudioCallbackMs,
        snapshot.p99AudioCallbackMs,
        snapshot.maxAudioCallbackMs));
    obj.Set("mixEngine", MakeMetricObject(
        env,
        snapshot.blockCount,
        snapshot.avgProcessBlockMs,
        snapshot.p50ProcessBlockMs,
        snapshot.p95ProcessBlockMs,
        snapshot.p99ProcessBlockMs,
        snapshot.maxProcessBlockMs));

    obj.Set("callbackP50Us", JsonApi::Number::New(env, snapshot.p50AudioCallbackMs * 1000.0));
    obj.Set("callbackP95Us", JsonApi::Number::New(env, snapshot.p95AudioCallbackMs * 1000.0));
    obj.Set("callbackP99Us", JsonApi::Number::New(env, snapshot.p99AudioCallbackMs * 1000.0));
    obj.Set("callbackMaxUs", JsonApi::Number::New(env, snapshot.maxAudioCallbackMs * 1000.0));
    obj.Set("mixEngineP50Us", JsonApi::Number::New(env, snapshot.p50ProcessBlockMs * 1000.0));
    obj.Set("mixEngineP95Us", JsonApi::Number::New(env, snapshot.p95ProcessBlockMs * 1000.0));
    obj.Set("mixEngineP99Us", JsonApi::Number::New(env, snapshot.p99ProcessBlockMs * 1000.0));
    obj.Set("mixEngineMaxUs", JsonApi::Number::New(env, snapshot.maxProcessBlockMs * 1000.0));

    obj.Set("callbackOverrunCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.audioCallbackOverrunCount)));
    obj.Set("mixEngineOverrunCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.overrunBlockCount)));
    obj.Set("overBudgetBlockCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.overBudgetBlockCount)));
    obj.Set("droppedTelemetrySamples",
            JsonApi::Number::New(env, static_cast<double>(snapshot.droppedTelemetrySamples)));
    obj.Set("lockMissCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.chainLockMissCount)));
    obj.Set("chainLockMissCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.chainLockMissCount)));
    obj.Set("masterChainSkippedCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.masterChainSkippedCount)));
    obj.Set("trackChainSkippedCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.trackChainSkippedCount)));
    obj.Set("staleSnapshotReuseCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.staleSnapshotReuseCount)));
    obj.Set("guardedPluginCrashedSkippedCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.guardedPluginCrashedSkippedCount)));
    obj.Set("latencyEpochChanges",
            JsonApi::Number::New(env, static_cast<double>(snapshot.latencyEpochChangeCount)));
    obj.Set("compensationTargetChanges",
            JsonApi::Number::New(env, static_cast<double>(snapshot.pdcRetargetCount)));
    obj.Set("pdcDelayProcessCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.pdcDelayProcessCount)));
    obj.Set("nanInfBlockCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.nanInfBlockCount)));

    obj.Set("worstChainsByMax", MakeWorstScopeArray(env, snapshot.worstChainsByMax));
    obj.Set("worstChainsByP99", MakeWorstScopeArray(env, snapshot.worstChainsByP99));
    obj.Set("worstEffectsByMax", MakeWorstScopeArray(env, snapshot.worstEffectsByMax));
    obj.Set("worstEffectsByP99", MakeWorstScopeArray(env, snapshot.worstEffectsByP99));

    JsonApi::Object resonance = JsonApi::Object::New(env);
    resonance.Set("wolaCallCount",
                  JsonApi::Number::New(env, static_cast<double>(snapshot.resonanceSuppressorWolaCallCount)));
    resonance.Set("averageWolaUs",
                  JsonApi::Number::New(env, snapshot.avgResonanceSuppressorWolaMs * 1000.0));
    resonance.Set("maxWolaUs",
                  JsonApi::Number::New(env, snapshot.maxResonanceSuppressorWolaMs * 1000.0));
    resonance.Set("averageWolaMs",
                  JsonApi::Number::New(env, snapshot.avgResonanceSuppressorWolaMs));
    resonance.Set("p99WolaUs",
                  JsonApi::Number::New(env, snapshot.p99ResonanceSuppressorWolaMs * 1000.0));
    resonance.Set("p99WolaMs",
                  JsonApi::Number::New(env, snapshot.p99ResonanceSuppressorWolaMs));
    resonance.Set("maxWolaMs",
                  JsonApi::Number::New(env, snapshot.maxResonanceSuppressorWolaMs));
    resonance.Set("audioThreadReprepareCount",
                  JsonApi::Number::New(env, static_cast<double>(snapshot.resonanceSuppressorAudioThreadReprepareCount)));
    resonance.Set("deferredReprepareCount",
                  JsonApi::Number::New(env, static_cast<double>(snapshot.resonanceSuppressorDeferredReprepareCount)));
    resonance.Set("realtimeSafe",
                  JsonApi::Boolean::New(env, snapshot.highQualityResonanceSuppressorRealtimeSafe));
    resonance.Set("activeInstanceCount",
                  JsonApi::Number::New(env, static_cast<double>(
                      snapshot.activeResonanceSuppressorHighQualityInstanceCount)));
    resonance.Set("riskLevel",
                  JsonApi::String::New(env, snapshot.realtimeRsHqRiskLevel));
    resonance.Set("riskReasons",
                  MakeStringArray(env, snapshot.realtimeRsHqRiskReasons));
    resonance.Set("recommendedAction",
                  MakeStringArray(env, snapshot.recommendedAction));
    obj.Set("resonanceSuppressorHighQuality", resonance);
    obj.Set("resonanceSuppressorWolaCallCount",
            JsonApi::Number::New(env, static_cast<double>(snapshot.resonanceSuppressorWolaCallCount)));
    obj.Set("maxResonanceSuppressorWolaUs",
            JsonApi::Number::New(env, snapshot.maxResonanceSuppressorWolaMs * 1000.0));
    obj.Set("p99ResonanceSuppressorWolaUs",
            JsonApi::Number::New(env, snapshot.p99ResonanceSuppressorWolaMs * 1000.0));
    obj.Set("activeResonanceSuppressorHighQualityInstanceCount",
            JsonApi::Number::New(env, static_cast<double>(
                snapshot.activeResonanceSuppressorHighQualityInstanceCount)));
    obj.Set("realtimeRsHqRiskLevel",
            JsonApi::String::New(env, snapshot.realtimeRsHqRiskLevel));
    obj.Set("realtimeRsHqRiskReasons",
            MakeStringArray(env, snapshot.realtimeRsHqRiskReasons));
    obj.Set("recommendedAction",
            MakeStringArray(env, snapshot.recommendedAction));

    obj.Set("maxAudibleTrackLatencySamples",
            JsonApi::Number::New(env, static_cast<double>(presentationDiag.maxTrackLatencySamples)));
    obj.Set("masterInsertLatencySamples",
            JsonApi::Number::New(env, static_cast<double>(presentationDiag.masterLatencySamples)));
    obj.Set("audioDeviceOutputLatencySamples",
            JsonApi::Number::New(env, static_cast<double>(presentationDiag.deviceOutputLatencySamples)));
    obj.Set("livePresentationLatencySamples",
            JsonApi::Number::New(env, static_cast<double>(presentationDiag.totalPresentationLatencySamples)));
    obj.Set("rawPositionSamples",
            JsonApi::Number::New(env, static_cast<double>(rawPositionSamples)));
    obj.Set("presentationPositionSamples",
            JsonApi::Number::New(env, static_cast<double>(presentationPositionSamples)));
    obj.Set("diagnosis", JsonApi::String::New(env, snapshot.diagnosis));
    obj.Set("timingSequence",
            JsonApi::Number::New(env, static_cast<double>(snapshot.timingSequence)));

    return obj;
}

// startAudioPerformanceCapture(options) -> { status, durationSeconds, startedAt }
JsonApi::Value Audio_StartAudioPerformanceCapture(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    try
    {
        auto options = parseAudioPerformanceCaptureOptions(info);
        beginAudioPerformanceCapture(options);

        std::lock_guard<std::mutex> lock(g_audioPerformanceCaptureMutex);
        JsonApi::Object out = JsonApi::Object::New(env);
        out.Set("ok", JsonApi::Boolean::New(env, true));
        out.Set("status", JsonApi::String::New(env, "capturing"));
        out.Set("durationSeconds", JsonApi::Number::New(env, options.durationSeconds));
        out.Set("startedAt", JsonApi::String::New(env, g_audioPerformanceCapture.capturedAtIso));
        out.Set("startTimingSequence",
                JsonApi::Number::New(env,
                                  static_cast<double>(
                                      g_audioPerformanceCapture.minTimingSequence)));
        return out;
    }
    catch (const std::exception& e)
    {
        JsonApi::Error::New(env, e.what()).ThrowAsJavaScriptException();
        return JsonApi::Object::New(env);
    }
}

// stopAudioPerformanceCapture() -> report object
JsonApi::Value Audio_StopAudioPerformanceCapture(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    try
    {
        const auto report = finishAudioPerformanceCapture();
        return jsonToValue(env, report);
    }
    catch (const std::exception& e)
    {
        JsonApi::Error::New(env, e.what()).ThrowAsJavaScriptException();
        return JsonApi::Object::New(env);
    }
}

// exportAudioPerformanceCaptureReport(options) -> { jsonPath, markdownPath, report }
JsonApi::Value Audio_ExportAudioPerformanceCaptureReport(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    try
    {
        auto options = parseAudioPerformanceCaptureOptions(info);
        nlohmann::json report;
        {
            std::lock_guard<std::mutex> lock(g_audioPerformanceCaptureMutex);
            if (g_lastAudioPerformanceCaptureReport.is_null()
                || g_lastAudioPerformanceCaptureReport.empty())
            {
                throw std::runtime_error("no completed audio performance capture to export");
            }
            report = g_lastAudioPerformanceCaptureReport;
        }

        auto [jsonPath, markdownPath] =
            writeAudioPerformanceReportFiles(report, options);
        {
            std::lock_guard<std::mutex> lock(g_audioPerformanceCaptureMutex);
            g_lastAudioPerformanceCaptureJsonPath = jsonPath;
            g_lastAudioPerformanceCaptureMarkdownPath = markdownPath;
        }
        return makeCaptureResultObject(env, report, jsonPath, markdownPath);
    }
    catch (const std::exception& e)
    {
        JsonApi::Error::New(env, e.what()).ThrowAsJavaScriptException();
        return JsonApi::Object::New(env);
    }
}

// captureAudioPerformanceReport(options) -> { jsonPath, markdownPath, report }
JsonApi::Value Audio_CaptureAudioPerformanceReport(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    try
    {
        auto options = parseAudioPerformanceCaptureOptions(info);
        beginAudioPerformanceCapture(options);
        std::this_thread::sleep_for(std::chrono::seconds(options.durationSeconds));
        const auto report = finishAudioPerformanceCapture();
        auto [jsonPath, markdownPath] =
            writeAudioPerformanceReportFiles(report, options);
        {
            std::lock_guard<std::mutex> lock(g_audioPerformanceCaptureMutex);
            g_lastAudioPerformanceCaptureJsonPath = jsonPath;
            g_lastAudioPerformanceCaptureMarkdownPath = markdownPath;
        }
        return makeCaptureResultObject(env, report, jsonPath, markdownPath);
    }
    catch (const std::exception& e)
    {
        try
        {
            stopAudioPerformanceCaptureDrainThread();
            std::lock_guard<std::mutex> lock(g_audioPerformanceCaptureMutex);
            g_audioPerformanceCapture.active = false;
        }
        catch (...) {}
        JsonApi::Error::New(env, e.what()).ThrowAsJavaScriptException();
        return JsonApi::Object::New(env);
    }
}

