// audio_resetCrashedPlugin(trackId, nodeId) → boolean
// Attempts to recover a VST node that crashed inside processBlock.
// Returns true if the plugin is healthy again, false if it still faults.
JsonApi::Value Audio_ResetCrashedPlugin(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !audioEngine) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsNumber()) {
        JsonApi::TypeError::New(env, "audio_resetCrashedPlugin(trackId: number, nodeId: number)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }
    const int trackId = info[0].As<JsonApi::Number>().Int32Value();
    const int nodeId  = info[1].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("audio.resetCrashedPlugin");

    // Close any open editor first — if the plugin crashed, the editor may hold
    // dangling pointers into crashed state.  Reopening happens lazily on demand.
    audioEngine->getMixEngine().closePluginEditor(trackId, nodeId);

    const bool ok = audioEngine->getMixEngine().resetCrashedPlugin(trackId, nodeId);
    log.done("trackId=" + std::to_string(trackId) + " nodeId=" + std::to_string(nodeId)
             + " success=" + (ok ? "true" : "false"));
    return JsonApi::Boolean::New(env, ok);
}

// ── Load-crash breadcrumb + quarantine (P2, docs/PLUGIN_HOSTING_LOG.md) ──────
// Both manifest-dispatched (ui/rpc-manifest.js).

// audio_getLastLoadCrash() → { version, pid, format, name, vendor,
//   fileOrIdentifier, uniqueId, deprecatedUid, phase, context, ts,
//   quarantined: true } | null
// The breadcrumb of the third-party load that killed the previous engine,
// recovered (and quarantined) at engine start. Consuming it clears it, so the
// UI shows one notice per crash.
JsonApi::Value Audio_GetLastLoadCrash(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !audioEngine) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    auto& registry = audioEngine->getMixEngine().getPluginRegistry();
    const auto crash = registry.takeLastLoadCrash();
    if (!crash.isObject())
        return env.Null();
    const auto parsed = nlohmann::json::parse(juce::JSON::toString(crash).toStdString(),
                                              nullptr, /*allow_exceptions=*/false);
    if (parsed.is_discarded() || !parsed.is_object())
        return env.Null();
    std::fprintf(stderr, "[PluginHost] load-crash notice consumed: \"%s\" (%s)\n",
                 parsed.value("name", std::string()).c_str(),
                 parsed.value("phase", std::string()).c_str());
    return jsonToValue(env, parsed);
}

// audio_unquarantinePlugin(format: string, uniqueId: string|number,
//                          deprecatedUid: string|number)
//   → { ok: true, removed: boolean, resolved: number, failed: number }
//   | { ok: false, error: 'bad-args' }
// uniqueId/deprecatedUid: lower-case hex strings as reported by
// audio_getMissingPlugins / audio_getLastLoadCrash (a number is converted).
// Removes the quarantine entry, then retries every placeholder of that plugin
// through the existing tryResolvePlugin path (breadcrumb context
// "resolveMissing" — a repeat crash re-quarantines it).
JsonApi::Value Audio_UnquarantinePlugin(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !audioEngine) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    auto uidArg = [&](size_t i, juce::String& out) -> bool {
        if (info.Length() <= i) return false;
        if (info[i].IsString()) {
            out = PluginRegistry::normaliseUidHex(juce::String(info[i].As<JsonApi::String>().Utf8Value()));
            return out.isNotEmpty();
        }
        if (info[i].IsNumber()) {
            out = juce::String::toHexString(info[i].As<JsonApi::Number>().Int32Value()).toLowerCase();
            return true;
        }
        return false;
    };
    juce::String uid, depUid;
    if (info.Length() < 3 || !info[0].IsString() || !uidArg(1, uid) || !uidArg(2, depUid))
        return pluginOk(env, "bad-args");
    const juce::String format(info[0].As<JsonApi::String>().Utf8Value());
    BridgeCallLog log("audio.unquarantinePlugin");

    auto& mix      = audioEngine->getMixEngine();
    auto& registry = mix.getPluginRegistry();
    const bool removed = registry.unquarantine(format, uid, depUid);

    int resolved = 0, failed = 0;
    const auto missing = nlohmann::json::parse(mix.getMissingPluginsJSON(), nullptr, false);
    if (missing.is_array()) {
        for (const auto& m : missing) {
            if (m.value("pluginFormat", std::string()) != format.toStdString()) continue;
            if (PluginRegistry::normaliseUidHex(juce::String(m.value("uniqueId", std::string()))) != uid) continue;
            if (PluginRegistry::normaliseUidHex(juce::String(m.value("deprecatedUid", std::string()))) != depUid) continue;
            const int trackId = m.value("trackId", -2);
            const int nodeId  = m.value("nodeId", -1);
            if (trackId < -1 || nodeId < 0) continue;
            if (mix.tryResolvePlugin(trackId, nodeId)) ++resolved; else ++failed;
        }
    }

    auto obj = pluginOk(env, {});
    obj.Set("removed",  JsonApi::Boolean::New(env, removed));
    obj.Set("resolved", JsonApi::Number::New(env, resolved));
    obj.Set("failed",   JsonApi::Number::New(env, failed));
    log.done((format + " " + uid + "/" + depUid).toStdString()
             + " removed=" + (removed ? "true" : "false")
             + " resolved=" + std::to_string(resolved) + " failed=" + std::to_string(failed));
    return obj;
}

// ── Phase 2 render scoping helpers ───────────────────────────────────────────

// End of the last meaningful event (last clip / last pattern block) in ticks.
static int64_t computeFullTimelineEndTick(const Timeline& tl)
{
    int64_t endTick = 0;
    for (const auto* c : tl.getAllClips())
        if (c) endTick = std::max(endTick, (c->position + c->duration).ticks);
    for (const auto* b : tl.getAllPatternBlocks())
        if (b) endTick = std::max(endTick, (b->position + b->duration).ticks);
    return endTick;
}

// Resolve the render scope from the project LoopRegion (the user-facing source
// of truth). The legacy renderer "Start Bar / End Bar" inputs, if supplied, are
// honoured ONLY as a debug-only override of the region bounds — never in normal
// user exports. The override is parsed behind XLETH_DEBUG; note the real
// user-facing gate is the renderer hiding those inputs outside
// import.meta.env.DEV, because XLETH_DEBUG is defined unconditionally in this
// project's native build.
static xleth::RenderScope resolveExportScope(const Timeline& tl,
                                             bool hasStartBeat, double startBeat,
                                             bool hasEndBeat, double endBeat)
{
    xleth::RenderScopeOverride dbg;
#ifdef XLETH_DEBUG
    if (hasStartBeat || hasEndBeat) {
        const double sB = hasStartBeat ? startBeat : 0.0;
        const double eB = hasEndBeat   ? endBeat   : -1.0;
        if (eB > sB) {   // a real explicit range — treat as a debug bounds repoint
            dbg.active    = true;
            dbg.startTick = RenderClock::beatsToPPQ(sB);
            dbg.endTick   = RenderClock::beatsToPPQ(eB);
            std::fprintf(stderr,
                "[LoopRegion] debug bounds override active: [%lld,%lld) ticks\n",
                (long long)dbg.startTick, (long long)dbg.endTick);
        }
    }
#else
    (void)hasStartBeat; (void)startBeat; (void)hasEndBeat; (void)endBeat;
#endif
    return xleth::computeRenderScope(tl.getLoopRegion(),
                                     computeFullTimelineEndTick(tl), dbg);
}

// ── Audio export (offline render to WAV/MP3/FLAC) ────────────────────────────

// audio_exportStart({ outputPath, format, sampleRate, bitDepth, mp3Bitrate,
//                     flacLevel }) → bool
// Render scope derives from the project LoopRegion (Phase 2). startBeat/endBeat,
// if present, are a debug-only bounds override (see resolveExportScope).
JsonApi::Value Audio_ExportStart(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !sampleBank) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return JsonApi::Boolean::New(env, false);
    }
    if (info.Length() < 1 || !info[0].IsObject()) {
        JsonApi::TypeError::New(env, "audio_exportStart({...config})").ThrowAsJavaScriptException();
        return JsonApi::Boolean::New(env, false);
    }
    if (g_exportRunning.load()) {
        return JsonApi::Boolean::New(env, false); // already running
    }

    JsonApi::Object o = info[0].As<JsonApi::Object>();

    AudioExporter::Config cfg;
    if (o.Has("outputPath")) cfg.outputPath = o.Get("outputPath").As<JsonApi::String>().Utf8Value();
    if (cfg.outputPath.empty()) {
        JsonApi::TypeError::New(env, "outputPath required").ThrowAsJavaScriptException();
        return JsonApi::Boolean::New(env, false);
    }

    if (o.Has("format")) {
        std::string fmt = o.Get("format").As<JsonApi::String>().Utf8Value();
        if (fmt == "mp3")       cfg.format = AudioExporter::Format::MP3;
        else if (fmt == "flac") cfg.format = AudioExporter::Format::FLAC;
        else                    cfg.format = AudioExporter::Format::WAV;
    }
    if (o.Has("sampleRate")) cfg.sampleRate = o.Get("sampleRate").As<JsonApi::Number>().Int32Value();
    if (o.Has("bitDepth"))   cfg.bitDepth   = o.Get("bitDepth").As<JsonApi::Number>().Int32Value();
    if (o.Has("mp3Bitrate")) cfg.mp3Bitrate = o.Get("mp3Bitrate").As<JsonApi::Number>().Int32Value();
    if (o.Has("flacLevel"))  cfg.flacLevel  = o.Get("flacLevel").As<JsonApi::Number>().Int32Value();

    // Loudness normalisation (opt-in; absent fields keep AudioExporter::Config's
    // off-by-default values, so a caller that omits all four gets byte-identical
    // behaviour to pre-normalization exports).
    if (o.Has("normalizationEnabled")) cfg.normalizationEnabled = o.Get("normalizationEnabled").As<JsonApi::Boolean>().Value();
    if (o.Has("targetLufs"))           cfg.targetLufs           = o.Get("targetLufs").As<JsonApi::Number>().DoubleValue();
    if (o.Has("maxDbtp"))              cfg.maxDbtp              = o.Get("maxDbtp").As<JsonApi::Number>().DoubleValue();
    if (o.Has("allowUpwardGain"))      cfg.allowUpwardGain      = o.Get("allowUpwardGain").As<JsonApi::Boolean>().Value();

    // Phase 2: render scope is derived from the project LoopRegion. startBeat /
    // endBeat (if present) are a debug-only bounds override, not a user range.
    {
        const bool hasS = o.Has("startBeat");
        const bool hasE = o.Has("endBeat");
        const double sB = hasS ? o.Get("startBeat").As<JsonApi::Number>().DoubleValue() : 0.0;
        const double eB = hasE ? o.Get("endBeat").As<JsonApi::Number>().DoubleValue()   : 0.0;
        const auto scope = resolveExportScope(*g_timeline, hasS, sB, hasE, eB);
        cfg.startBeat = RenderClock::ppqToBeats(scope.captureStartTick);
        cfg.endBeat   = RenderClock::ppqToBeats(scope.captureEndTick);
        // Absolute window warms up from tick 0 (warmUpStartTick) so in-flight
        // notes / effect tails survive into the first captured sample.
        cfg.warmUpStartBeat = scope.scoped
            ? RenderClock::ppqToBeats(scope.warmUpStartTick)
            : -1.0;   // full timeline: legacy latency-only pre-roll
        // Tail policy from the project LoopRegion (built at the export sample
        // rate). hardCut → no tail; tailClamp → ring out effects past the capture
        // end; wrap (Phase 3B) → fold the post-end tail onto the region head for a
        // seamless loop. resolveTailPlanForScope fails wrap CLOSED to tailClamp for
        // a non-scoped (full-timeline) render — there is no region head to fold.
        const int srForTail = cfg.sampleRate > 0 ? cfg.sampleRate : 44100;
        cfg.tail = xleth::resolveTailPlanForScope(g_timeline->getLoopRegion(),
                                                  static_cast<double>(srForTail),
                                                  scope.scoped);
        std::fprintf(stderr,
            "[RenderScope] audio scoped=%s capture=[%.3f,%.3f) warmUpBeat=%.3f "
            "tail=%s capSamples=%lld\n",
            scope.scoped ? "true" : "false",
            cfg.startBeat, cfg.endBeat, cfg.warmUpStartBeat,
            xleth::tailRenderModeName(cfg.tail.mode),
            (long long)cfg.tail.maxTailSamples);
    }

    // Reset state
    {
        std::lock_guard<std::mutex> lk(g_exportStateMutex);
        g_exportProgress.running    = true;
        g_exportProgress.percent    = 0.0f;
        g_exportProgress.phase      = "rendering";
        g_exportProgress.outputPath = cfg.outputPath;
        g_exportProgress.error.clear();
        g_exportProgress.hasNormalizationReport = false;
    }
    g_exportCancel.store(false);
    g_exportRunning.store(true);

    // Join the prior thread handle before replacing it. The g_exportRunning
    // guard above means that export has already finished (its body clears
    // the flag as its last statement), so this returns at once; it used to
    // detach, which also worked, but Shutdown now joins the same handle and
    // one policy is easier to keep correct than two.
    if (g_exportThread && g_exportThread->joinable()) {
        g_exportThread->join();
    }

    // Suspend audio device callback so the render thread has exclusive
    // MixEngine access — prevents concurrent processBlock() races that
    // corrupt pattern-track sampler state and timing.
    audioEngine->suspendCallback();

    // Prepare the MixEngine HERE, on the host bridge main thread, which is also the
    // JUCE message thread (ScopedJuceInitialiser_GUI was created on it).
    // JUCE's AudioProcessorGraph::prepareToPlay() only builds its render
    // sequence synchronously when called from the message thread; from any
    // other thread it defers via triggerAsyncUpdate().  If we called prepare()
    // inside the spawned thread, processBlock() would fire with a stale render
    // sequence whose settings don't match, causing JUCE to call audio.clear()
    // on every track buffer that has an effect chain — silencing the export.
    {
        auto& mixer = audioEngine->getMixEngine();
        const int sr = cfg.sampleRate > 0 ? cfg.sampleRate : 44100;
        mixer.setNonRealtime(true);
        mixer.prepare(static_cast<double>(sr), 4096);
        // Warm + await the clip render cache at the EXPORT rate so pitched/
        // stretched clips hit the cache (which applies pitch) instead of the
        // rate-corrected-but-pitchless raw fallback. Must run after prepare()
        // so cache keys are built at the export rate, on the message thread,
        // before the render thread spawns. The Clip-mode transform table is
        // published first, with no settle, so the shifted renders are keyed
        // (and awaited) on the transform the export will actually play.
        mixer.prepareSourceTransformsForExport();
        refreshAllClipCaches();
        waitForClipCachesReady(15000);
    }

    g_exportThread = std::make_unique<std::thread>([cfg]() {
        std::cout << "[Bridge] → audio.export start path=" << cfg.outputPath << "\n" << std::flush;

        auto& mixer = audioEngine->getMixEngine();
        // setNonRealtime(true) and prepare() already called on the message
        // thread above — do NOT repeat here (would re-trigger async rebuild).

        AudioExporter exporter;
        AudioExporter::NormalizationReport normReport;
        bool ok = false;
        try {
            ok = exporter.exportAudio(
                *g_timeline,
                *sampleBank,
                mixer,
                cfg,
                [](float p) {
                    std::lock_guard<std::mutex> lk(g_exportStateMutex);
                    g_exportProgress.percent = p;
                    g_exportProgress.phase = (p < 0.7f) ? "rendering" : "encoding";
                },
                g_exportCancel,
                &normReport
            );
        } catch (const std::exception& e) {
            std::lock_guard<std::mutex> lk(g_exportStateMutex);
            g_exportProgress.error = e.what();
            ok = false;
        } catch (...) {
            std::lock_guard<std::mutex> lk(g_exportStateMutex);
            g_exportProgress.error = "unknown exception";
            ok = false;
        }

        // Restore MixEngine state and resume audio device callback. resumeCallback()
        // re-runs audioDeviceAboutToStart -> MixEngine::prepare() with the LIVE
        // device settings, but it runs here on the EXPORT thread, so each effect
        // chain's AudioProcessorGraph only gets a *deferred* render-sequence
        // rebuild. Flag the restore so the message thread re-prepares for real;
        // resuming here regardless keeps the device running either way.
        mixer.setNonRealtime(false);
        audioEngine->resumeCallback();
        g_exportPendingRealtimeRestore.store(true, std::memory_order_release);

        {
            std::lock_guard<std::mutex> lk(g_exportStateMutex);
            if (g_exportCancel.load())      g_exportProgress.phase = "cancelled";
            else if (ok)                    { g_exportProgress.phase = "done"; g_exportProgress.percent = 1.0f; }
            else if (g_exportProgress.phase != "cancelled") g_exportProgress.phase = "error";
            g_exportProgress.running = false;

            if (ok && !g_exportCancel.load() && cfg.normalizationEnabled) {
                g_exportProgress.hasNormalizationReport = true;
                g_exportProgress.normalizationApplied   = normReport.applied;
                g_exportProgress.normalizationMeasuredIntegratedLufs = normReport.measuredIntegratedLufs;
                g_exportProgress.normalizationMeasuredTruePeakDbtp   = normReport.measuredTruePeakDbtp;
                g_exportProgress.normalizationLoudnessGainDb         = normReport.loudnessGainDb;
                g_exportProgress.normalizationPeakSafetyGainDb       = normReport.peakSafetyGainDb;
                g_exportProgress.normalizationFinalPredictedIntegratedLufs = normReport.finalPredictedIntegratedLufs;
                g_exportProgress.normalizationFinalPredictedTruePeakDbtp   = normReport.finalPredictedTruePeakDbtp;
            } else {
                g_exportProgress.hasNormalizationReport = false;
            }
        }
        g_exportRunning.store(false);

        std::cout << "[Bridge] ← audio.export " << (ok ? "done" : "stopped") << "\n" << std::flush;
    });

    return JsonApi::Boolean::New(env, true);
}

// audio_exportGetProgress() → { running, percent, phase, outputPath, error }
JsonApi::Value Audio_ExportGetProgress(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();

    // Message-thread half of the export teardown. The export thread sets the
    // flag before it clears `running`, so any poll that observes a finished
    // export also observes the flag. Re-preparing here (on the message thread)
    // rebuilds each effect chain's render sequence synchronously, which is what
    // the export thread's own resumeCallback() could not do.
    if (g_exportPendingRealtimeRestore.load(std::memory_order_acquire)
        && !g_exportRunning.load()
        && g_exportPendingRealtimeRestore.exchange(false, std::memory_order_acq_rel)
        && audioEngine != nullptr)
    {
        audioEngine->getMixEngine().prepare(audioEngine->getSampleRate(),
                                            audioEngine->getBufferSize());
    }

    JsonApi::Object o = JsonApi::Object::New(env);
    std::lock_guard<std::mutex> lk(g_exportStateMutex);
    o.Set("running",    JsonApi::Boolean::New(env, g_exportProgress.running));
    o.Set("percent",    JsonApi::Number::New(env, g_exportProgress.percent));
    o.Set("phase",      JsonApi::String::New(env, g_exportProgress.phase));
    o.Set("outputPath", JsonApi::String::New(env, g_exportProgress.outputPath));
    o.Set("error",      JsonApi::String::New(env, g_exportProgress.error));
    if (g_exportProgress.hasNormalizationReport) {
        JsonApi::Object norm = JsonApi::Object::New(env);
        norm.Set("applied",                        JsonApi::Boolean::New(env, g_exportProgress.normalizationApplied));
        norm.Set("measuredIntegratedLufs",         JsonApi::Number::New (env, g_exportProgress.normalizationMeasuredIntegratedLufs));
        norm.Set("measuredTruePeakDbtp",           JsonApi::Number::New (env, g_exportProgress.normalizationMeasuredTruePeakDbtp));
        norm.Set("loudnessGainDb",                 JsonApi::Number::New (env, g_exportProgress.normalizationLoudnessGainDb));
        norm.Set("peakSafetyGainDb",                JsonApi::Number::New (env, g_exportProgress.normalizationPeakSafetyGainDb));
        norm.Set("finalPredictedIntegratedLufs",   JsonApi::Number::New (env, g_exportProgress.normalizationFinalPredictedIntegratedLufs));
        norm.Set("finalPredictedTruePeakDbtp",     JsonApi::Number::New (env, g_exportProgress.normalizationFinalPredictedTruePeakDbtp));
        o.Set("normalization", norm);
    }
    return o;
}

// audio_exportCancel() → bool
JsonApi::Value Audio_ExportCancel(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    g_exportCancel.store(true);
    return JsonApi::Boolean::New(env, true);
}

// ── Video export (offline A/V render via OfflineRenderer) ────────────────────

// Message thread. Points MixEngine back at the live timeline after a video
// export (or a failed start) and, when edits landed during the export, rebuilds
// the MixEngine state their handlers could only derive from the frozen copy.
// Called with the device callback still suspended, so the swap cannot race the
// audio thread.
static void restoreLiveTimelineAfterExport(const char* why) {
    if (!g_mixOnExportTimeline) return;
    g_mixOnExportTimeline = false;
    const bool edited = g_timelineEditedDuringExport;
    g_timelineEditedDuringExport = false;
    if (!audioEngine || !g_timeline) return;
    auto& mix = audioEngine->getMixEngine();
    mix.setTimeline(g_timeline.get());   // also resyncs track slots + envelope/LFO definitions
    if (edited) {
        mix.rebuildAllSamplers();
        mix.syncSidechainTargetBuses();
        mix.refreshAutomationPlan();
    }
    std::fprintf(stderr, "[ExportSnapshot] MixEngine back on the live timeline (%s)%s\n",
                 why, edited ? "; edits made during the export resynced" : "");
}

// video_exportStart({ outputPath, videoCodec, hwEncoder, width, height,
//                     fpsNum, fpsDen, crf, videoBitrate,
//                     audioCodec, sampleRate, audioBitrate,
//                     startBeat, endBeat,
//                     useSourceMedia /* bool, default true — when false the
//                                       render reads DNxHR proxy media instead
//                                       of original-source files. Final export
//                                       must leave this true so CRF/bitrate
//                                       settings operate on full-quality
//                                       pixels. */ }) → bool
JsonApi::Value Video_ExportStart(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();

    // Auto-init GPU device if not yet created (UI doesn't expose GPU selection yet)
    if (!g_gpuDevice) {
        g_gpuDevice = std::make_unique<GpuDeviceManager>();
        if (g_gpuDevice->detectAdapters()) {
            int defaultIdx = g_gpuDevice->getDefaultAdapterIndex();
            g_gpuDevice->createDevice(defaultIdx >= 0 ? defaultIdx : -1);
        }
    }

    if (!isInitialised() || !g_timeline || !g_gpuDevice) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return JsonApi::Boolean::New(env, false);
    }
    if (info.Length() < 1 || !info[0].IsObject()) {
        JsonApi::TypeError::New(env, "video_exportStart({...config})").ThrowAsJavaScriptException();
        return JsonApi::Boolean::New(env, false);
    }

    // Reject if already running
    if (g_videoRenderer && g_videoRenderer->isRunning()) {
        return JsonApi::Boolean::New(env, false);
    }

    // [ExportSnapshot] Freeze the model for this export (spec Ruling 7). Every
    // read below, the render thread's OfflineRenderer AND its MixEngine blocks,
    // goes to this copy, so an edit made while the export runs (move a clip,
    // edit notes, add a track) can neither race it nor change its output.
    // Taken under the model lock so it never sees a half-applied edit. Data
    // only: media, decoders and caches live outside Timeline. Ids are kept, so
    // every id-keyed engine cache stays valid against the copy.
    FrozenTimelineCopy frozen;
    {
        std::lock_guard<std::recursive_mutex> lock(syncEventsMutex);
        frozen = makeFrozenTimelineCopy(*g_timeline);
    }
    const Timeline& exportTimeline = *frozen.timeline;
    std::fprintf(stderr,
        "[ExportSnapshot] froze the timeline for export in %.2f ms "
        "(%zu clips, %zu tracks, %zu patterns, %zu blocks)\n",
        frozen.copyMs, exportTimeline.getAllClips().size(),
        exportTimeline.getAllTracks().size(), exportTimeline.getAllPatterns().size(),
        exportTimeline.getAllPatternBlocks().size());

    JsonApi::Object o = info[0].As<JsonApi::Object>();

    ExportSettings settings;
    if (o.Has("outputPath")) settings.outputPath = o.Get("outputPath").As<JsonApi::String>().Utf8Value();
    if (settings.outputPath.empty()) {
        JsonApi::TypeError::New(env, "outputPath required").ThrowAsJavaScriptException();
        return JsonApi::Boolean::New(env, false);
    }

    // Video codec
    if (o.Has("videoCodec")) {
        std::string vc = o.Get("videoCodec").As<JsonApi::String>().Utf8Value();
        if      (vc == "h264")   settings.videoCodec = ExportSettings::VideoCodec::H264;
        else if (vc == "h265")   settings.videoCodec = ExportSettings::VideoCodec::H265;
        else if (vc == "av1")    settings.videoCodec = ExportSettings::VideoCodec::AV1;
        else if (vc == "dnxhd")  settings.videoCodec = ExportSettings::VideoCodec::DNXHD;
        else if (vc == "prores") settings.videoCodec = ExportSettings::VideoCodec::PRORES;
        else                     settings.videoCodec = ExportSettings::VideoCodec::MPEG4;
    }
    if (o.Has("hwEncoder")) settings.hwEncoderName = o.Get("hwEncoder").As<JsonApi::String>().Utf8Value();
    if (o.Has("videoMode")) {
        std::string vm = o.Get("videoMode").As<JsonApi::String>().Utf8Value();
        if      (vm == "software") settings.videoMode = ExportSettings::VideoMode::Software;
        else if (vm == "hardware") settings.videoMode = ExportSettings::VideoMode::Hardware;
        else                       settings.videoMode = ExportSettings::VideoMode::Auto;
    }
    if (o.Has("width"))     settings.width     = o.Get("width").As<JsonApi::Number>().Int32Value();
    if (o.Has("height"))    settings.height    = o.Get("height").As<JsonApi::Number>().Int32Value();
    if (o.Has("fpsNum"))    settings.fpsNum    = o.Get("fpsNum").As<JsonApi::Number>().Int32Value();
    if (o.Has("fpsDen"))    settings.fpsDen    = o.Get("fpsDen").As<JsonApi::Number>().Int32Value();
    // Canvas fit (how the project canvas maps when the export aspect differs).
    // Absent / unknown → Stretch, which is the legacy fill behavior.
    if (o.Has("fitMode") && o.Get("fitMode").IsString()) {
        std::string fm = o.Get("fitMode").As<JsonApi::String>().Utf8Value();
        if      (fm == "crop") settings.fitMode = ExportSettings::FitMode::Crop;
        else if (fm == "bars") settings.fitMode = ExportSettings::FitMode::Bars;
        else                   settings.fitMode = ExportSettings::FitMode::Stretch;
    }
    // Rate-control mode is explicit (UI sends "crf" or "bitrate"). When absent we
    // leave the struct default (CRF) and rely on the crf<0 sentinel for legacy
    // callers. This is what stops the CRF default from leaking into bitrate-mode
    // exports and silently overriding the requested bitrate.
    if (o.Has("rateControl")) {
        std::string rcs = o.Get("rateControl").As<JsonApi::String>().Utf8Value();
        settings.rateControl = (rcs == "bitrate")
            ? ExportSettings::RateControl::Bitrate
            : ExportSettings::RateControl::CRF;
    }
    if (o.Has("crf"))       settings.crf       = o.Get("crf").As<JsonApi::Number>().Int32Value();
    if (o.Has("videoBitrate")) settings.videoBitrate = o.Get("videoBitrate").As<JsonApi::Number>().Int64Value();

    // Audio codec
    if (o.Has("audioCodec")) {
        std::string ac = o.Get("audioCodec").As<JsonApi::String>().Utf8Value();
        if      (ac == "opus")      settings.audioCodec = ExportSettings::AudioCodec::OPUS;
        else if (ac == "flac")      settings.audioCodec = ExportSettings::AudioCodec::FLAC;
        else if (ac == "pcm_s16le") settings.audioCodec = ExportSettings::AudioCodec::PCM_S16LE;
        else                        settings.audioCodec = ExportSettings::AudioCodec::AAC;
    }
    if (o.Has("sampleRate"))   settings.sampleRate   = o.Get("sampleRate").As<JsonApi::Number>().Int32Value();
    if (o.Has("audioBitrate")) settings.audioBitrate  = o.Get("audioBitrate").As<JsonApi::Number>().Int32Value();

    // Render input: default true → original source media. UI sets this
    // explicitly; engine struct also defaults to true so a missing field is
    // safe. Set false only for a deliberate preview-quality export.
    if (o.Has("useSourceMedia"))
        settings.useSourceMedia = o.Get("useSourceMedia").As<JsonApi::Boolean>().Value();

    // Phase 2: render scope is derived from the project LoopRegion. startBeat /
    // endBeat (if present) are a debug-only bounds override, not a user range.
    const bool hasStartBeat = o.Has("startBeat");
    const bool hasEndBeat   = o.Has("endBeat");
    const double startBeatArg = hasStartBeat ? o.Get("startBeat").As<JsonApi::Number>().DoubleValue() : 0.0;
    const double endBeatArg   = hasEndBeat   ? o.Get("endBeat").As<JsonApi::Number>().DoubleValue()   : 0.0;
    const auto scope = resolveExportScope(exportTimeline, hasStartBeat, startBeatArg,
                                          hasEndBeat, endBeatArg);

    // Convert ticks → samples. Four distinct concepts (spec §5): warm-up start,
    // capture start, capture end, and the output timestamp (always 0).
    const double bpm = exportTimeline.getBPM();
    const double sampleRate = static_cast<double>(settings.sampleRate);
    const int64_t startSample = RenderClock::ppqToSample(scope.captureStartTick, settings.sampleRate, bpm);
    const int64_t endSample   = RenderClock::ppqToSample(scope.captureEndTick,   settings.sampleRate, bpm);
    // Scoped absolute window warms up from tick 0; full timeline / unscoped uses
    // legacy latency-only pre-roll (warm-up == capture start).
    const int64_t warmUpStartSample = scope.scoped
        ? RenderClock::ppqToSample(scope.warmUpStartTick, settings.sampleRate, bpm)
        : startSample;

    std::fprintf(stderr,
        "[RenderScope] video scoped=%s capture=[%lld,%lld) warmUpSample=%lld outputStart=0\n",
        scope.scoped ? "true" : "false",
        (long long)startSample, (long long)endSample, (long long)warmUpStartSample);

    if (endSample <= startSample) {
        JsonApi::Error::New(env, "Export range is empty (endSample <= startSample)").ThrowAsJavaScriptException();
        return JsonApi::Boolean::New(env, false);
    }

    // Suspend audio device callback so the render thread has exclusive
    // MixEngine access — prevents concurrent processBlock() races that
    // corrupt pattern-track sampler state and timing.
    audioEngine->suspendCallback();
    g_audioSuspendedForExport.store(true);

    // Audio half of the freeze. With the device callback suspended the render
    // thread is MixEngine's only reader, so its timeline can be swapped here
    // (before prepare(), which also clears the latency-reset flag setTimeline
    // raises). Restored on the message thread when the export ends.
    audioEngine->getMixEngine().setTimeline(frozen.timeline.get());
    g_mixOnExportTimeline = true;
    g_timelineEditedDuringExport = false;

    // [PreviewUnify] Pause GPU preview to avoid D3D11 context contention
    g_previewPauseForExport.store(true);

    // Prepare the MixEngine on the message thread before the render thread
    // starts — same reason as Audio_ExportStart above.  512 matches the
    // OfflineRenderer's kBufferSize constant.  The OfflineRenderer will call
    // prepare() again inside renderImpl() on the render thread; because the
    // params are identical, JUCE's signature check skips a redundant rebuild
    // so the render sequence built here remains valid for the first block.
    {
        auto& mixer = audioEngine->getMixEngine();
        mixer.setNonRealtime(true);
        mixer.prepare(static_cast<double>(settings.sampleRate), 512);
        // Warm + await the clip render cache at the EXPORT rate (see audio
        // export above) so pitched/stretched clips hit the cache rather than the
        // pitchless raw fallback. Message thread, before the render thread spawns.
        mixer.prepareSourceTransformsForExport();
        refreshAllClipCaches();
        waitForClipCachesReady(15000);
    }

    // Create the renderer (destroys any prior instance — joins its thread via dtor)
    g_videoRenderer = std::make_unique<OfflineRenderer>(
        exportTimeline,
        audioEngine->getMixEngine(),
        *g_gpuDevice
    );

    // Resolution-aware render proxies are cached/generated in the project proxies
    // dir (same as preview proxies). Enables fast-export (useSourceMedia=false);
    // ignored for full-quality export.
    // The previous export's copy dies here, after the renderer that referenced it.
    g_exportTimeline = frozen.timeline;

    if (g_projectManager)
        g_videoRenderer->setProxiesDir(g_projectManager->getProxiesDir());

    // Tail policy from the project LoopRegion (built at the export sample rate).
    // Must be set before startRender (captured by the render thread). hardCut → no
    // tail; tailClamp → ring out effects + freeze last video frame; wrap (Phase
    // 3B) → fold the post-end audio tail onto the region head (video is NOT frozen
    // or extended). resolveTailPlanForScope fails wrap CLOSED to tailClamp for a
    // non-scoped (full-timeline) render.
    {
        const auto tailPlan = xleth::resolveTailPlanForScope(
            exportTimeline.getLoopRegion(), sampleRate, scope.scoped);
        g_videoRenderer->setTailRenderPlan(tailPlan);
        std::fprintf(stderr,
            "[RenderScope] video tail=%s capSamples=%lld holdSamples=%lld\n",
            xleth::tailRenderModeName(tailPlan.mode),
            (long long)tailPlan.maxTailSamples, (long long)tailPlan.holdSamples);
    }

    bool ok = g_videoRenderer->startRender(startSample, endSample, warmUpStartSample, settings);
    if (!ok) {
        JsonApi::Error::New(env, "Failed to start video render").ThrowAsJavaScriptException();
        g_videoRenderer.reset();
        restoreLiveTimelineAfterExport("export failed to start");
        audioEngine->resumeCallback();
        g_audioSuspendedForExport.store(false);
        return JsonApi::Boolean::New(env, false);
    }

    std::fprintf(stderr, "[Bridge] → video.export start path=%s range=%lld–%lld samples\n",
                 settings.outputPath.c_str(), (long long)startSample, (long long)endSample);
    return JsonApi::Boolean::New(env, true);
}

// video_exportGetProgress() → { running, percentage, phase, currentFrame,
//                                totalFrames, speed, eta, error, complete, failed }
JsonApi::Value Video_ExportGetProgress(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    JsonApi::Object o = JsonApi::Object::New(env);

    if (!g_videoRenderer) {
        o.Set("running",      JsonApi::Boolean::New(env, false));
        o.Set("percentage",   JsonApi::Number::New(env, 0.0));
        o.Set("phase",        JsonApi::Number::New(env, 0));
        o.Set("currentFrame", JsonApi::Number::New(env, 0));
        o.Set("totalFrames",  JsonApi::Number::New(env, 0));
        o.Set("speed",        JsonApi::Number::New(env, 0.0));
        o.Set("eta",          JsonApi::Number::New(env, 0.0));
        o.Set("error",        JsonApi::String::New(env, ""));
        o.Set("complete",     JsonApi::Boolean::New(env, false));
        o.Set("failed",       JsonApi::Boolean::New(env, false));
        return o;
    }

    const auto& p = g_videoRenderer->getProgress();
    const bool isRunning = g_videoRenderer->isRunning();

    // Resume audio device callback once the render thread has stopped
    if (!isRunning && g_audioSuspendedForExport.exchange(false)) {
        restoreLiveTimelineAfterExport("export finished");
        audioEngine->resumeCallback();
        std::fprintf(stderr, "[Bridge] Audio callback resumed after video export\n");

        // [PreviewUnify] Resume GPU preview compositing
        g_previewPauseForExport.store(false);
    }

    o.Set("running",      JsonApi::Boolean::New(env, isRunning));
    o.Set("percentage",   JsonApi::Number::New(env, static_cast<double>(p.percentage.load())));
    o.Set("phase",        JsonApi::Number::New(env, p.phase.load()));
    o.Set("currentFrame", JsonApi::Number::New(env, static_cast<double>(p.currentFrame.load())));
    o.Set("totalFrames",  JsonApi::Number::New(env, static_cast<double>(p.totalFrames.load())));
    o.Set("speed",        JsonApi::Number::New(env, static_cast<double>(p.speedMultiplier.load())));
    o.Set("eta",          JsonApi::Number::New(env, static_cast<double>(p.etaSeconds.load())));
    o.Set("error",                JsonApi::String::New(env, p.getError()));
    o.Set("videoEncoderName",     JsonApi::String::New(env, p.getVideoEncoderName()));
    o.Set("videoEncoderFallback", JsonApi::Boolean::New(env, p.videoEncoderFallback.load()));
    o.Set("complete",             JsonApi::Boolean::New(env, p.complete.load()));
    o.Set("failed",               JsonApi::Boolean::New(env, p.failed.load()));

    return o;
}

// video_exportCancel() → bool
JsonApi::Value Video_ExportCancel(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (g_videoRenderer) {
        g_videoRenderer->requestCancel();
        return JsonApi::Boolean::New(env, true);
    }
    return JsonApi::Boolean::New(env, false);
}

// video_computeDurationSeconds(startBeat, endBeat) → number
// Phase 3A: the estimate now derives from the SAME render scope the real export
// uses — the project LoopRegion (via resolveExportScope) — plus the tail policy.
// In production the manual Start/End Bar inputs are hidden, so the renderer sends
// (0, -1); those reach here as a debug-only bounds override that is inert outside
// XLETH_DEBUG, so the estimate reflects the scoped loop region (not the full
// timeline) and is NOT driven by stale hidden manual-bar values.
//
// The real tail length is unknown before render, so the estimate adds the tail
// CAP (tailMaxSeconds) for tailClamp; hardCut adds nothing. wrap (Phase 3B) also
// adds NOTHING: its tail folds back into the region head, so the exported file is
// exactly the region length — the cap is internal working audio, not output.
// NOTE: Assumes constant tempo. Update if tempo automation lands.
JsonApi::Value Video_ComputeDurationSeconds(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!g_timeline) return JsonApi::Number::New(env, 0.0);

    const bool   hasS = info.Length() >= 1 && info[0].IsNumber();
    const bool   hasE = info.Length() >= 2 && info[1].IsNumber();
    const double sB   = hasS ? info[0].As<JsonApi::Number>().DoubleValue() : 0.0;
    const double eB   = hasE ? info[1].As<JsonApi::Number>().DoubleValue() : -1.0;

    const double bpm = g_timeline->getBPM();
    if (bpm <= 0.0) return JsonApi::Number::New(env, 0.0);

    // Same scope resolution as the export start paths (LoopRegion-derived; debug
    // bounds override only under XLETH_DEBUG with an explicit eB > sB).
    const auto scope = resolveExportScope(*g_timeline, hasS, sB, hasE, eB);
    const double captureBeats =
        RenderClock::ppqToBeats(scope.captureEndTick - scope.captureStartTick);
    double seconds = std::max(0.0, captureBeats * 60.0 / bpm);

    // Add the tail cap (rate cancels: maxTailSamples / sr == tailMaxSeconds).
    // Scope-aware so wrap (which folds, adding no duration) stays region-length,
    // and a non-scoped wrap fall-back (→ tailClamp) is estimated with the cap.
    constexpr double kNominalSr = 48000.0;
    const auto tail = xleth::resolveTailPlanForScope(
        g_timeline->getLoopRegion(), kNominalSr, scope.scoped);
    if (tail.mode == xleth::TailRenderMode::TailClamp)
        seconds += static_cast<double>(tail.maxTailSamples) / kNominalSr;

    return JsonApi::Number::New(env, seconds);
}

// ── Sample Export / Swap ──────────────────────────────────────────────────────

namespace {

// Probe audio stream info (native sample rate + duration) via FFmpeg.
// Returns { 44100, 0.0 } on failure.
// (Struct + forward declaration live above Project_Load — see ~line 2724.)
ProbedAudioInfo probeAudioInfo(const std::string& filePath)
{
    ProbedAudioInfo out{ 44100, 0.0 };
    AVFormatContext* fmt = nullptr;
    if (avformat_open_input(&fmt, filePath.c_str(), nullptr, nullptr) < 0)
        return out;
    if (avformat_find_stream_info(fmt, nullptr) >= 0) {
        if (fmt->duration != AV_NOPTS_VALUE)
            out.duration = static_cast<double>(fmt->duration) / AV_TIME_BASE;
        for (unsigned int i = 0; i < fmt->nb_streams; ++i) {
            if (fmt->streams[i]->codecpar->codec_type == AVMEDIA_TYPE_AUDIO) {
                out.sampleRate = fmt->streams[i]->codecpar->sample_rate;
                break;
            }
        }
    }
    avformat_close_input(&fmt);
    return out;
}

// Append a WAV smpl chunk (root note) to an existing WAV file, then update
// the RIFF size field at offset 4. The smpl chunk is 44 bytes (8 hdr + 36 data).
void appendSmplChunk(const juce::File& file, int rootNote, double sampleRate)
{
    if (rootNote < 0 || !file.existsAsFile()) return;

    juce::FileOutputStream fout(file, 0); // 0 = unbuffered, supports setPosition
    if (!fout.openedOk()) return;

    const int64_t fileSize = file.getSize();

    auto writeLe32 = [&](uint32_t v) {
        uint8_t b[4] = { (uint8_t)v, (uint8_t)(v>>8), (uint8_t)(v>>16), (uint8_t)(v>>24) };
        fout.write(b, 4);
    };

    // Append smpl chunk at end
    fout.setPosition(fileSize);
    fout.write("smpl", 4);
    writeLe32(36);                                                // chunk data size
    writeLe32(0);                                                 // Manufacturer
    writeLe32(0);                                                 // Product
    writeLe32(sampleRate > 0
        ? static_cast<uint32_t>(1000000000.0 / sampleRate) : 0); // Sample Period (ns)
    writeLe32(static_cast<uint32_t>(rootNote));                   // MIDI Unity Note
    writeLe32(0);                                                 // MIDI Pitch Fraction
    writeLe32(0);                                                 // SMPTE Format
    writeLe32(0);                                                 // SMPTE Offset
    writeLe32(0);                                                 // Num Sample Loops
    writeLe32(0);                                                 // Sampler Data

    // Update RIFF size at offset 4: new RIFF size = (fileSize + 44) - 8
    const uint32_t newRiffSize = static_cast<uint32_t>(fileSize - 8 + 44);
    fout.setPosition(4);
    writeLe32(newRiffSize);
    fout.flush();
}

} // namespace

// audio_exportRegion(regionId) → { success, path, duration }
// Decodes the region audio at native source sample rate and writes it to
// exports/{SourceName}_{Label}_{RegionName}.wav. Appends a smpl chunk if
// region.rootNote >= 0.
JsonApi::Value Audio_ExportRegion(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !sampleBank || !g_projectManager)
        return fail("Engine not initialised.");
    if (info.Length() < 1 || !info[0].IsNumber())
        return fail("audio_exportRegion(regionId: number)");
    if (!g_projectManager->hasProjectDir())
        return fail("No project directory — save project first.");

    const int regionId = info[0].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("audio.exportRegion");

    const SampleRegion* region = g_timeline->getRegion(regionId);
    if (!region) return fail("Region not found.");

    const SourceMedia* source = g_timeline->getSource(region->sourceId);
    if (!source) return fail("Source not found for region.");

    // Build filename using the caller-supplied naming format (default: sampleNameOnly).
    const std::string format = (info.Length() >= 2 && info[1].IsString())
        ? info[1].As<JsonApi::String>().Utf8Value()
        : "sampleNameOnly";
    const std::string srcStem = juce::File(juce::String(source->fileName))
                                     .getFileNameWithoutExtension()
                                     .toStdString();
    const std::string labelStr = sampleLabelToString(region->label);
    std::string filename = buildExportFilename(srcStem, labelStr, region->name, format);

    const std::string outputPath = g_projectManager->getExportsDir() + "/" + filename;

    // Swap-aware: if the region has swapped-in audio (edited via Sample Sandbox and
    // applied through Swap Audio), export THAT file in full rather than re-decoding
    // the original source at [startTime, endTime] — mirrors Audio_LoadRegionAudio.
    int sampleId = -1;
    int nativeRate = 0;
    if (region->hasSwappedAudio && !region->swappedAudioPath.empty()) {
        const auto probed = probeAudioInfo(region->swappedAudioPath);
        nativeRate = probed.sampleRate;
        const double endT = probed.duration > 0.0 ? probed.duration : 3600.0;
        sampleId = sampleBank->loadSampleFromSource(
            region->swappedAudioPath, 0.0, endT, static_cast<double>(nativeRate));
    } else {
        // Probe the source's native sample rate — export at native rate, no resampling.
        nativeRate = probeAudioInfo(source->filePath).sampleRate;
        // Decode region audio with nativeRate as target so SWR is a no-op (src==dst).
        sampleId = sampleBank->loadSampleFromSource(
            source->filePath, region->startTime, region->endTime,
            static_cast<double>(nativeRate));
    }
    if (sampleId < 0) return fail("Audio decode failed.");

    const juce::AudioBuffer<float>* buf = sampleBank->getSample(sampleId);
    if (!buf || buf->getNumSamples() == 0) return fail("Empty audio buffer.");

    // Write WAV using JUCE (clean, cross-platform, handles format correctly)
    juce::WavAudioFormat wavFmt;
    auto outFile = juce::File(juce::String(outputPath)); // auto avoids most-vexing-parse
    auto outStream = outFile.createOutputStream();
    if (!outStream || !outStream->openedOk())
        return fail("Cannot create output file.");

    std::unique_ptr<juce::AudioFormatWriter> writer(
        wavFmt.createWriterFor(
            outStream.release(),                          // WavAudioFormat takes ownership
            static_cast<double>(nativeRate),
            static_cast<unsigned int>(buf->getNumChannels()),
            16, {}, 0));
    if (!writer) return fail("WAV writer creation failed.");

    writer->writeFromAudioSampleBuffer(*buf, 0, buf->getNumSamples());
    writer.reset(); // flush + close file

    // Append smpl chunk with root note (file must be closed first)
    // Slot 0 is the region's own audio, which is what this export writes.
    if (region->slot(0).rootNote >= 0)
        appendSmplChunk(outFile, region->slot(0).rootNote, static_cast<double>(nativeRate));

    // Actual written duration, not the (possibly stale, swap-agnostic) region span.
    const double duration = static_cast<double>(buf->getNumSamples()) / nativeRate;
    log.done(filename);

    JsonApi::Object result = JsonApi::Object::New(env);
    result.Set("success",  JsonApi::Boolean::New(env, true));
    result.Set("path",     JsonApi::String::New(env, outputPath));
    result.Set("duration", JsonApi::Number::New(env, duration));
    return result;
}

// audio_swapRegionAudio(regionId, processedFilePath) → { success, swappedPath }
// Copies the processed WAV to swapped/, loads it into SampleBank at engine rate,
// remaps the region in MixEngine, and sets region.hasSwappedAudio = true.
JsonApi::Value Audio_SwapRegionAudio(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !sampleBank || !audioEngine || !g_projectManager)
        return fail("Engine not initialised.");
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsString())
        return fail("audio_swapRegionAudio(regionId: number, processedFilePath: string)");
    if (!g_projectManager->hasProjectDir())
        return fail("No project directory — save project first.");

    const int regionId = info[0].As<JsonApi::Number>().Int32Value();
    const std::string srcPath = info[1].As<JsonApi::String>().Utf8Value();
    BridgeCallLog log("audio.swapRegionAudio");

    SampleRegion* region = g_timeline->getRegionMutable(regionId);
    if (!region) return fail("Region not found.");

    auto srcFile = juce::File(juce::String(srcPath));
    if (!srcFile.existsAsFile()) return fail("Processed file not found.");

    // Copy to swapped/, overwriting any previous swap for this filename
    const std::string destPath = g_projectManager->getSwappedDir() + "/"
                                 + srcFile.getFileName().toStdString();
    auto destFile = juce::File(juce::String(destPath));
    if (destFile.existsAsFile()) destFile.deleteFile();
    if (!srcFile.copyFileTo(destFile)) return fail("File copy to swapped/ failed.");

    // Load swapped audio at engine rate. Probe real file duration first —
    // passing a huge endTime (e.g. 999999.0) makes SampleBank reserve a buffer
    // sized for that duration, which blows the allocator.
    const auto probed = probeAudioInfo(destPath);
    const double endT = probed.duration > 0.0 ? probed.duration : 3600.0;
    const double engineRate = g_timeline->getSampleRate();
    const int sampleId = sampleBank->loadSampleFromSource(destPath, 0.0, endT, engineRate);
    if (sampleId < 0) return fail("Failed to decode swapped audio.");
    triggerMipmapGeneration(sampleId, destPath, /*saveXlpeak=*/true);

    audioEngine->getMixEngine().mapRegionToSample(regionId, sampleId);
    refreshSamplerForRegion(regionId);

    region->swappedAudioPath        = destPath;
    region->hasSwappedAudio         = true;
    region->swappedAudioDurationSec = probed.duration > 0.0 ? probed.duration : 0.0;

    log.done(destFile.getFileName().toStdString());

    JsonApi::Object result = JsonApi::Object::New(env);
    result.Set("success",     JsonApi::Boolean::New(env, true));
    result.Set("swappedPath", JsonApi::String::New(env, destPath));
    return result;
}

// audio_revertRegionAudio(regionId) → { success }
// Reloads the original region audio from its source file, remaps it in
// MixEngine, and clears region.hasSwappedAudio.
JsonApi::Value Audio_RevertRegionAudio(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !sampleBank || !audioEngine)
        return fail("Engine not initialised.");
    if (info.Length() < 1 || !info[0].IsNumber())
        return fail("audio_revertRegionAudio(regionId: number)");

    const int regionId = info[0].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("audio.revertRegionAudio");

    SampleRegion* region = g_timeline->getRegionMutable(regionId);
    if (!region) return fail("Region not found.");

    const SourceMedia* source = g_timeline->getSource(region->sourceId);
    if (!source) return fail("Source not found for region.");

    const double engineRate = g_timeline->getSampleRate();
    const int sampleId = sampleBank->loadSampleFromSource(
        source->filePath, region->startTime, region->endTime, engineRate);
    if (sampleId < 0) return fail("Failed to decode original audio.");
    triggerMipmapGeneration(sampleId, source->filePath, /*saveXlpeak=*/false);

    audioEngine->getMixEngine().mapRegionToSample(regionId, sampleId);
    refreshSamplerForRegion(regionId);

    region->swappedAudioPath        = "";
    region->hasSwappedAudio         = false;
    region->swappedAudioDurationSec = 0.0;

    log.done(region->name);

    JsonApi::Object result = JsonApi::Object::New(env);
    result.Set("success", JsonApi::Boolean::New(env, true));
    return result;
}

// audio_loadRegionAudio(regionId) → sampleId
// Swap-aware: decodes from the region's swappedAudioPath if hasSwappedAudio is
// set, otherwise from the region's source at [startTime, endTime]. Loads into
// SampleBank and maps the region → sample in MixEngine. Returns -1 on failure.
JsonApi::Value Audio_LoadRegionAudio(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised() || !g_timeline || !sampleBank || !audioEngine) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return JsonApi::Number::New(env, -1);
    }
    if (info.Length() < 1 || !info[0].IsNumber()) {
        JsonApi::TypeError::New(env, "audio_loadRegionAudio(regionId: number)")
            .ThrowAsJavaScriptException();
        return JsonApi::Number::New(env, -1);
    }

    const int regionId = info[0].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("audio.loadRegionAudio");

    const SampleRegion* region = g_timeline->getRegion(regionId);
    if (!region) {
        log.done("no region");
        return JsonApi::Number::New(env, -1);
    }

    const double engineRate = audioEngine->getSampleRate();
    int sampleId = -1;

    std::string mipmapSourcePath;
    bool mipmapSaveXlpeak = false;

    if (region->hasSwappedAudio && !region->swappedAudioPath.empty()) {
        const auto probed = probeAudioInfo(region->swappedAudioPath);
        const double endT = probed.duration > 0.0 ? probed.duration : 3600.0;
        sampleId = sampleBank->loadSampleFromSource(
            region->swappedAudioPath, 0.0, endT, engineRate);
        mipmapSourcePath = region->swappedAudioPath;
        mipmapSaveXlpeak = true;
    } else {
        const SourceMedia* source = g_timeline->getSource(region->sourceId);
        if (!source) { log.done("no source"); return JsonApi::Number::New(env, -1); }
        sampleId = sampleBank->loadSampleFromSource(
            source->filePath, region->startTime, region->endTime, engineRate);
        mipmapSourcePath = source->filePath;
    }

    if (sampleId < 0) { log.done("decode failed"); return JsonApi::Number::New(env, -1); }
    triggerMipmapGeneration(sampleId, mipmapSourcePath, mipmapSaveXlpeak);

    fprintf(stderr, "[PITCHDBG] audio_loadRegionAudio: mapRegionToSample region=%d sampleId=%d\n",
            regionId, sampleId);
    fflush(stderr);
    audioEngine->getMixEngine().mapRegionToSample(regionId, sampleId);

    // Now that this region's audio is mapped, warm clip caches for any clips
    // referencing it that have non-identity processing params (pitch/stretch/reverse).
    // This is critical for project reload — refreshAllClipCaches() runs before
    // region audio is loaded, so clips miss their initial cache warm.
    {
        auto& mix = audioEngine->getMixEngine();
        for (const Clip* c : g_timeline->getAllClips()) {
            if (!c || c->regionId != regionId) continue;
            if (mix.clipNeedsCacheRender(*c)) mix.invalidateClipCache(c->id, "audio_loadRegionAudio");
        }
    }

    log.done(std::to_string(sampleId));
    return JsonApi::Number::New(env, sampleId);
}

// ─── Sample slots (layers) ───────────────────────────────────────────────────
// Slot 0 always plays the region's own audio, so it has no dedicated loader —
// changing it is what audio_swapRegionAudio already does, and that path is
// untouched by these handlers. Slots 1..7 own an independent file copied into
// the project's slots/ directory.
//
// Every one of these mutates the Timeline through UndoManager
// (SetSamplerSettingsCommand carries the whole slot vector), so add / remove /
// retarget are all undoable in one step.

// Copy `srcPath` into the project's slots/ dir, decode it into SampleBank, and
// register it for {regionId, slotIndex}. Returns the destination path, or an
// empty string on failure (with `err` set).
static std::string installSlotAudio(int regionId, int slotIndex,
                                    const std::string& srcPath,
                                    std::string& err)
{
    if (!g_projectManager || !g_projectManager->hasProjectDir()) {
        err = "No project directory — save project first.";
        return {};
    }
    if (!sampleBank || !audioEngine || !g_timeline) {
        err = "Engine not initialised.";
        return {};
    }

    auto srcFile = juce::File(juce::String(srcPath));
    if (!srcFile.existsAsFile()) { err = "Audio file not found."; return {}; }

    // Namespace the copy by region+slot so two slots that load the same file
    // (or the same slot reloaded) never collide in slots/.
    const std::string destName = "r" + std::to_string(regionId)
                               + "_s" + std::to_string(slotIndex) + "_"
                               + srcFile.getFileName().toStdString();
    const std::string destPath = g_projectManager->getSlotsDir() + "/" + destName;

    auto destFile = juce::File(juce::String(destPath));
    destFile.getParentDirectory().createDirectory();
    if (destFile.existsAsFile()) destFile.deleteFile();
    if (!srcFile.copyFileTo(destFile)) { err = "File copy to slots/ failed."; return {}; }

    // Probe first: passing a huge endTime makes SampleBank reserve a buffer for
    // that duration, which blows the allocator.
    const auto probed = probeAudioInfo(destPath);
    const double endT = probed.duration > 0.0 ? probed.duration : 3600.0;
    const double engineRate = audioEngine->getSampleRate();

    const int sampleId = sampleBank->loadSampleFromSource(destPath, 0.0, endT, engineRate);
    if (sampleId < 0) { err = "Failed to decode slot audio."; return {}; }
    triggerMipmapGeneration(sampleId, destPath, /*saveXlpeak=*/true);

    audioEngine->getMixEngine().mapRegionSlotToSample(regionId, slotIndex, sampleId);
    return destPath;
}

// timeline_addSampleSlot(regionId, filePath) → { success, slotIndex?, error? }
// Appends a new layer carrying its own audio. Fails when the region already
// holds MAX_SAMPLE_SLOTS layers.
JsonApi::Value Timeline_AddSampleSlot(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !g_undoManager) return fail("Engine not initialised.");
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsString())
        return fail("timeline_addSampleSlot(regionId: number, filePath: string)");

    const int regionId = info[0].As<JsonApi::Number>().Int32Value();
    const std::string srcPath = info[1].As<JsonApi::String>().Utf8Value();
    BridgeCallLog log("timeline.addSampleSlot");

    const SampleRegion* r = g_timeline->getRegion(regionId);
    if (!r) return fail("Region not found.");
    if (r->slotCount() >= MAX_SAMPLE_SLOTS) return fail("All 8 slots are in use.");

    const int newIndex = r->slotCount();

    std::string err;
    const std::string destPath = installSlotAudio(regionId, newIndex, srcPath, err);
    if (destPath.empty()) return fail(err.c_str());

    SamplerSettings s = samplerSettingsFromRegion(*r);
    SampleSlot slot;
    slot.audioFilePath = destPath;
    slot.name = juce::File(juce::String(destPath)).getFileNameWithoutExtension().toStdString();
    // A fresh layer starts neutral: same root note as slot 0 so it plays in
    // unison until the user tunes it.
    slot.rootNote = r->slot(0).rootNote;
    s.slots.push_back(std::move(slot));

    g_undoManager->execute(
        std::make_unique<SetSamplerSettingsCommand>(regionId, s, *g_timeline), *g_timeline);
    refreshSamplerForRegion(regionId);

    log.done("slot " + std::to_string(newIndex));

    JsonApi::Object out = JsonApi::Object::New(env);
    out.Set("success",   JsonApi::Boolean::New(env, true));
    out.Set("slotIndex", JsonApi::Number::New(env, newIndex));
    return out;
}

// timeline_removeSampleSlot(regionId, slotIndex) → { success, error? }
// Slot 0 cannot be removed — it IS the region's own sample.
JsonApi::Value Timeline_RemoveSampleSlot(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !g_undoManager) return fail("Engine not initialised.");
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsNumber())
        return fail("timeline_removeSampleSlot(regionId: number, slotIndex: number)");

    const int regionId  = info[0].As<JsonApi::Number>().Int32Value();
    const int slotIndex = info[1].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("timeline.removeSampleSlot");

    const SampleRegion* r = g_timeline->getRegion(regionId);
    if (!r) return fail("Region not found.");
    if (slotIndex <= 0) return fail("Slot 1 holds the region's own sample and cannot be removed.");
    if (slotIndex >= r->slotCount()) return fail("Slot index out of range.");

    SamplerSettings s = samplerSettingsFromRegion(*r);
    s.slots.erase(s.slots.begin() + slotIndex);
    if (s.slots.empty()) s.slots.emplace_back();

    g_undoManager->execute(
        std::make_unique<SetSamplerSettingsCommand>(regionId, s, *g_timeline), *g_timeline);

    // Removing a slot shifts every higher slot down by one, so the whole
    // {regionId, slot} → SampleBank table for this region is rebuilt from the
    // post-command slot list rather than patched.
    auto& mix = audioEngine->getMixEngine();
    mix.unmapAllRegionSlots(regionId);
    if (const SampleRegion* updated = g_timeline->getRegion(regionId)) {
        for (int i = 1; i < updated->slotCount(); ++i) {
            const std::string& path = updated->slot(i).audioFilePath;
            if (path.empty()) continue;
            std::string err;
            installSlotAudio(regionId, i, path, err);
        }
    }
    refreshSamplerForRegion(regionId);

    log.done("slot " + std::to_string(slotIndex));

    JsonApi::Object out = JsonApi::Object::New(env);
    out.Set("success", JsonApi::Boolean::New(env, true));
    return out;
}

// timeline_setSlotAudio(regionId, slotIndex, filePath) → { success, error? }
// Retargets one layer's audio, leaving that slot's tuning/level/trim/loop —
// and every other slot — untouched. Slot 0 is rejected: swapping the region's
// own audio is audio_swapRegionAudio's job.
JsonApi::Value Timeline_SetSlotAudio(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !g_undoManager) return fail("Engine not initialised.");
    if (info.Length() < 3 || !info[0].IsNumber() || !info[1].IsNumber() || !info[2].IsString())
        return fail("timeline_setSlotAudio(regionId: number, slotIndex: number, filePath: string)");

    const int regionId  = info[0].As<JsonApi::Number>().Int32Value();
    const int slotIndex = info[1].As<JsonApi::Number>().Int32Value();
    const std::string srcPath = info[2].As<JsonApi::String>().Utf8Value();
    BridgeCallLog log("timeline.setSlotAudio");

    const SampleRegion* r = g_timeline->getRegion(regionId);
    if (!r) return fail("Region not found.");
    if (slotIndex <= 0) return fail("Use audio_swapRegionAudio to change slot 1's audio.");
    if (slotIndex >= r->slotCount()) return fail("Slot index out of range.");

    std::string err;
    const std::string destPath = installSlotAudio(regionId, slotIndex, srcPath, err);
    if (destPath.empty()) return fail(err.c_str());

    SamplerSettings s = samplerSettingsFromRegion(*r);
    // Audio only — the slot keeps every setting it already had.
    s.slots[static_cast<size_t>(slotIndex)].audioFilePath = destPath;
    s.slots[static_cast<size_t>(slotIndex)].name =
        juce::File(juce::String(destPath)).getFileNameWithoutExtension().toStdString();

    g_undoManager->execute(
        std::make_unique<SetSamplerSettingsCommand>(regionId, s, *g_timeline), *g_timeline);
    refreshSamplerForRegion(regionId);

    log.done("slot " + std::to_string(slotIndex));

    JsonApi::Object out = JsonApi::Object::New(env);
    out.Set("success", JsonApi::Boolean::New(env, true));
    return out;
}

// Render slot 0's own audio to a standalone WAV in the project's slots/ dir.
// Slot 0 has no file of its own when the region is unswapped — its PCM is
// decoded on the fly from the source at [startTime, endTime] — so duplicating
// it needs a real file to feed installSlotAudio the same way slots 1..7
// already have one. Caller deletes the returned staging file once
// installSlotAudio has copied it into its final namespaced destination.
static std::string renderRegionAudioToTempFile(int regionId, std::string& err)
{
    if (!g_timeline || !sampleBank || !g_projectManager) { err = "Engine not initialised."; return {}; }
    const SampleRegion* region = g_timeline->getRegion(regionId);
    if (!region) { err = "Region not found."; return {}; }
    const SourceMedia* source = g_timeline->getSource(region->sourceId);
    if (!source) { err = "Source not found for region."; return {}; }

    const int nativeRate = probeAudioInfo(source->filePath).sampleRate;
    const int sampleId = sampleBank->loadSampleFromSource(
        source->filePath, region->startTime, region->endTime,
        static_cast<double>(nativeRate));
    if (sampleId < 0) { err = "Audio decode failed."; return {}; }

    const juce::AudioBuffer<float>* buf = sampleBank->getSample(sampleId);
    if (!buf || buf->getNumSamples() == 0) { err = "Empty audio buffer."; return {}; }

    const std::string tempPath = g_projectManager->getSlotsDir() + "/_dup_stage_"
                                + std::to_string(regionId) + ".wav";
    auto outFile = juce::File(juce::String(tempPath));
    outFile.getParentDirectory().createDirectory();
    if (outFile.existsAsFile()) outFile.deleteFile();
    auto outStream = outFile.createOutputStream();
    if (!outStream || !outStream->openedOk()) { err = "Cannot create staging file."; return {}; }

    juce::WavAudioFormat wavFmt;
    std::unique_ptr<juce::AudioFormatWriter> writer(
        wavFmt.createWriterFor(
            outStream.release(), static_cast<double>(nativeRate),
            static_cast<unsigned int>(buf->getNumChannels()), 16, {}, 0));
    if (!writer) { err = "WAV writer creation failed."; return {}; }
    writer->writeFromAudioSampleBuffer(*buf, 0, buf->getNumSamples());
    writer.reset();  // flush + close before the caller reads it back

    return tempPath;
}

// timeline_duplicateSampleSlot(regionId, sourceSlotIndex) → { success, slotIndex?, error? }
// Appends a new layer that is a full copy of an existing one: a fresh copy of
// its audio file AND every tuning/level/trim/loop/MANGLE/PREP/destructive-flag
// setting the source slot carries — everything but the mute/solo flags, so the
// new layer starts audible even if the one it was copied from was soloed.
// Slot 0's audio has no standalone file of its own (its PCM comes from the
// region, decoded on the fly), so duplicating it renders that audio to a WAV
// first — the swapped file directly if the region has one, otherwise a fresh
// decode of the region's own [startTime, endTime] range from source.
JsonApi::Value Timeline_DuplicateSampleSlot(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !g_undoManager) return fail("Engine not initialised.");
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsNumber())
        return fail("timeline_duplicateSampleSlot(regionId: number, sourceSlotIndex: number)");

    const int regionId        = info[0].As<JsonApi::Number>().Int32Value();
    const int sourceSlotIndex = info[1].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("timeline.duplicateSampleSlot");

    const SampleRegion* r = g_timeline->getRegion(regionId);
    if (!r) return fail("Region not found.");
    if (sourceSlotIndex < 0 || sourceSlotIndex >= r->slotCount())
        return fail("Source slot index out of range.");
    if (r->slotCount() >= MAX_SAMPLE_SLOTS) return fail("All 8 slots are in use.");

    const int newIndex = r->slotCount();

    std::string err;
    bool stagedTempFile = false;
    std::string srcPath;
    if (sourceSlotIndex == 0) {
        if (r->hasSwappedAudio && !r->swappedAudioPath.empty()) {
            srcPath = r->swappedAudioPath;
        } else {
            srcPath = renderRegionAudioToTempFile(regionId, err);
            if (srcPath.empty()) return fail(err.c_str());
            stagedTempFile = true;
        }
    } else {
        srcPath = r->slot(sourceSlotIndex).audioFilePath;
        if (srcPath.empty()) return fail("Source slot has no audio file.");
    }

    const std::string destPath = installSlotAudio(regionId, newIndex, srcPath, err);
    if (stagedTempFile) juce::File(juce::String(srcPath)).deleteFile();
    if (destPath.empty()) return fail(err.c_str());

    SamplerSettings s = samplerSettingsFromRegion(*r);
    SampleSlot slot = r->slot(sourceSlotIndex);   // full copy: tuning/level/trim/loop/mangle/prep/flags
    slot.audioFilePath = destPath;
    slot.name = slot.name.empty()
        ? juce::File(juce::String(destPath)).getFileNameWithoutExtension().toStdString()
        : slot.name + " copy";
    slot.mute = false;
    slot.solo = false;
    s.slots.push_back(std::move(slot));

    g_undoManager->execute(
        std::make_unique<SetSamplerSettingsCommand>(regionId, s, *g_timeline), *g_timeline);
    refreshSamplerForRegion(regionId);

    log.done("slot " + std::to_string(newIndex) + " <- " + std::to_string(sourceSlotIndex));

    JsonApi::Object out = JsonApi::Object::New(env);
    out.Set("success",   JsonApi::Boolean::New(env, true));
    out.Set("slotIndex", JsonApi::Number::New(env, newIndex));
    return out;
}

// audio_probeAudioDuration(filePath) → number (seconds, 0 on failure)
// Needed by UI to fetch waveform peaks from a swapped audio file.
JsonApi::Value Audio_ProbeAudioDuration(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (info.Length() < 1 || !info[0].IsString()) {
        JsonApi::TypeError::New(env, "audio_probeAudioDuration(filePath: string)")
            .ThrowAsJavaScriptException();
        return JsonApi::Number::New(env, 0.0);
    }
    const std::string path = info[0].As<JsonApi::String>().Utf8Value();
    return JsonApi::Number::New(env, probeAudioInfo(path).duration);
}

// ─── Sample Video Export / Swap ─────────────────────────────────────────────
// Mirrors the Sample Audio Export/Swap feature above, but for the VIDEO stream
// only — the region's audio (audioFilePath / swappedAudioPath) is never
// touched by any of these three functions.

// Find a clip referencing regionId on a non-fullscreen track and (re)schedule
// its proxy transcode. Same clip-selection logic as timeline_modifyRegion's
// trim-change branch (XlethEngineService.cpp, Timeline_ModifyRegion) — kept as
// a private helper here since both Swap and Revert Video need it.
static void reenqueueRegionProxy(int regionId, bool forceRetranscode = false) {
    if (!g_timeline) return;
    const GridLayout& gl = g_timeline->getGridLayout();
    std::unordered_set<int> fullscreenTracks;
    for (const auto& fl : gl.fullscreenLayers) {
        if (fl.trackId >= 0) fullscreenTracks.insert(fl.trackId);
    }
    for (const Clip* c : g_timeline->getAllClips()) {
        if (!c || c->regionId != regionId) continue;
        if (fullscreenTracks.count(c->trackId)) continue;
        maybeEnqueueRegionProxy(regionId, c->trackId, forceRetranscode);
        break;  // dedup in ProxyManager; one trigger is enough
    }
}

// Mux a VIDEO-ONLY file (already fully encoded, e.g. by
// ProxyTranscoder::transcodeSectionHQX) together with a separately-decoded PCM
// audio buffer into one output .mov. The video stream is STREAM-COPIED — it is
// already final-quality DNxHR, so re-decoding/re-encoding it here would only
// cost time and generation loss for nothing. The audio buffer is freshly
// encoded to PCM_S16LE: lossless, and needs no swr resampling since the caller
// decodes the buffer at exactly `audioSampleRate` already. audioBuffer may be
// nullptr/empty (source had no decodable audio) — the output is then a valid,
// playable video-only .mov.
static bool muxVideoSectionWithAudio(const std::string& videoOnlyPath,
                                     const juce::AudioBuffer<float>* audioBuffer,
                                     double audioSampleRate,
                                     const std::string& outputPath)
{
    AVFormatContext* inFmt          = nullptr;
    AVFormatContext* outFmt         = nullptr;
    AVCodecContext*  audEnc         = nullptr;
    AVFrame*         audFrame       = nullptr;
    AVPacket*        pkt            = av_packet_alloc();
    bool             headerWritten  = false;
    int              inVideoIdx     = -1;
    AVStream*        outVideoStream = nullptr;
    AVStream*        outAudioStream = nullptr;

    auto cleanup = [&]() {
        if (headerWritten && outFmt) av_write_trailer(outFmt);
        if (pkt)      av_packet_free(&pkt);
        if (audFrame) av_frame_free(&audFrame);
        if (audEnc)   avcodec_free_context(&audEnc);
        if (outFmt) {
            if (!(outFmt->oformat->flags & AVFMT_NOFILE) && outFmt->pb)
                avio_closep(&outFmt->pb);
            avformat_free_context(outFmt);
        }
        if (inFmt) avformat_close_input(&inFmt);
    };

    if (avformat_open_input(&inFmt, videoOnlyPath.c_str(), nullptr, nullptr) < 0) {
        std::cerr << "[Video Export] Failed to reopen encoded video for muxing: "
                  << videoOnlyPath << "\n";
        cleanup(); return false;
    }
    if (avformat_find_stream_info(inFmt, nullptr) < 0) { cleanup(); return false; }
    inVideoIdx = av_find_best_stream(inFmt, AVMEDIA_TYPE_VIDEO, -1, -1, nullptr, 0);
    if (inVideoIdx < 0) {
        std::cerr << "[Video Export] No video stream in encoded section\n";
        cleanup(); return false;
    }
    AVStream* inVideoStream = inFmt->streams[inVideoIdx];

    if (avformat_alloc_output_context2(&outFmt, nullptr, "mov", outputPath.c_str()) < 0 || !outFmt) {
        cleanup(); return false;
    }

    outVideoStream = avformat_new_stream(outFmt, nullptr);
    if (!outVideoStream ||
        avcodec_parameters_copy(outVideoStream->codecpar, inVideoStream->codecpar) < 0) {
        cleanup(); return false;
    }
    outVideoStream->codecpar->codec_tag = 0;   // let the mov muxer pick its own fourcc
    outVideoStream->time_base = inVideoStream->time_base;

    // Open + validate the PCM encoder BEFORE calling avformat_new_stream for it —
    // once a stream is added to outFmt there is no API to remove it, so on the
    // (unlikely) chance avcodec_open2 fails we must not have created the stream
    // yet, or avformat_write_header would choke on a stream with no codecpar.
    const bool wantAudio = audioBuffer && audioBuffer->getNumSamples() > 0 && audioSampleRate > 0.0;
    if (wantAudio) {
        const AVCodec* audCodec = avcodec_find_encoder(AV_CODEC_ID_PCM_S16LE);
        if (!audCodec) {
            std::cerr << "[Video Export] PCM_S16LE encoder unavailable — exporting video-only\n";
        } else {
            AVCodecContext* trialEnc = avcodec_alloc_context3(audCodec);
            trialEnc->sample_fmt  = AV_SAMPLE_FMT_S16;
            trialEnc->sample_rate = static_cast<int>(audioSampleRate);
            trialEnc->time_base   = AVRational{ 1, trialEnc->sample_rate };
            av_channel_layout_default(&trialEnc->ch_layout, audioBuffer->getNumChannels());
            if (outFmt->oformat->flags & AVFMT_GLOBALHEADER)
                trialEnc->flags |= AV_CODEC_FLAG_GLOBAL_HEADER;

            if (avcodec_open2(trialEnc, audCodec, nullptr) < 0) {
                std::cerr << "[Video Export] PCM encoder open failed — exporting video-only\n";
                avcodec_free_context(&trialEnc);
            } else {
                outAudioStream = avformat_new_stream(outFmt, nullptr);
                if (outAudioStream &&
                    avcodec_parameters_from_context(outAudioStream->codecpar, trialEnc) >= 0) {
                    audEnc = trialEnc;   // ownership transferred
                    outAudioStream->time_base = audEnc->time_base;
                } else {
                    outAudioStream = nullptr;
                    avcodec_free_context(&trialEnc);
                }
            }
        }
    }

    if (!(outFmt->oformat->flags & AVFMT_NOFILE) &&
        avio_open(&outFmt->pb, outputPath.c_str(), AVIO_FLAG_WRITE) < 0) {
        cleanup(); return false;
    }
    if (avformat_write_header(outFmt, nullptr) < 0) { cleanup(); return false; }
    headerWritten = true;

    // ── Stream-copy every video packet ────────────────────────────────────
    {
        AVPacket* vpkt = av_packet_alloc();
        while (vpkt && av_read_frame(inFmt, vpkt) >= 0) {
            if (vpkt->stream_index == inVideoIdx) {
                vpkt->stream_index = outVideoStream->index;
                av_packet_rescale_ts(vpkt, inVideoStream->time_base, outVideoStream->time_base);
                av_interleaved_write_frame(outFmt, vpkt);
            }
            av_packet_unref(vpkt);
        }
        if (vpkt) av_packet_free(&vpkt);
    }

    // ── Encode + write the PCM audio (if any) ─────────────────────────────
    if (outAudioStream && audEnc) {
        audFrame = av_frame_alloc();
        const int channels     = audioBuffer->getNumChannels();
        const int totalSamples = audioBuffer->getNumSamples();
        constexpr int kChunk   = 4096;
        std::vector<int16_t> interleaved(static_cast<size_t>(kChunk) * channels);
        int64_t samplePos = 0;

        auto drainAudioPackets = [&]() {
            while (true) {
                int rc = avcodec_receive_packet(audEnc, pkt);
                if (rc == AVERROR(EAGAIN) || rc == AVERROR_EOF) break;
                if (rc < 0) break;
                pkt->stream_index = outAudioStream->index;
                av_packet_rescale_ts(pkt, audEnc->time_base, outAudioStream->time_base);
                av_interleaved_write_frame(outFmt, pkt);
                av_packet_unref(pkt);
            }
        };

        for (int offset = 0; offset < totalSamples && audFrame; offset += kChunk) {
            const int n = std::min(kChunk, totalSamples - offset);
            for (int ch = 0; ch < channels; ++ch) {
                const float* src = audioBuffer->getReadPointer(ch, offset);
                for (int i = 0; i < n; ++i) {
                    const float s = std::clamp(src[i], -1.0f, 1.0f);
                    interleaved[static_cast<size_t>(i) * channels + ch] =
                        static_cast<int16_t>(std::lround(s * 32767.0f));
                }
            }
            av_frame_unref(audFrame);
            audFrame->nb_samples  = n;
            audFrame->format      = AV_SAMPLE_FMT_S16;
            audFrame->sample_rate = audEnc->sample_rate;
            av_channel_layout_copy(&audFrame->ch_layout, &audEnc->ch_layout);
            if (av_frame_get_buffer(audFrame, 0) < 0) break;
            if (av_frame_make_writable(audFrame) < 0) break;
            std::memcpy(audFrame->data[0], interleaved.data(),
                        static_cast<size_t>(n) * channels * sizeof(int16_t));
            audFrame->pts = samplePos;
            samplePos += n;

            if (avcodec_send_frame(audEnc, audFrame) < 0) break;
            drainAudioPackets();
        }
        avcodec_send_frame(audEnc, nullptr);   // flush
        drainAudioPackets();
    }

    cleanup();
    return true;
}

// video_exportRegion(regionId) → { success, path, duration }
// Re-encodes the region's TRIMMED section — decoded from the ORIGINAL source
// (never the DNxHR proxy) — to a DNxHR HQX .mov at exports/
// {SourceName}_{Label}_{RegionName}.mov, at source resolution/frame rate,
// including the section's audio. A frame-accurate cut needs a real re-encode:
// the original is almost always inter-frame (H.264 YouTube rips etc.), so a
// stream/file copy can only land on GOP boundaries, not the user's exact trim.
JsonApi::Value Video_ExportRegion(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !sampleBank || !g_projectManager)
        return fail("Engine not initialised.");
    if (info.Length() < 1 || !info[0].IsNumber())
        return fail("video_exportRegion(regionId: number)");
    if (!g_projectManager->hasProjectDir())
        return fail("No project directory — save project first.");

    const int regionId = info[0].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("video.exportRegion");

    const SampleRegion* region = g_timeline->getRegion(regionId);
    if (!region) return fail("Region not found.");

    const SourceMedia* source = g_timeline->getSource(region->sourceId);
    if (!source) return fail("Source not found for region.");
    if (!source->hasVideo) return fail("Region's source has no video stream.");

    auto srcFile = juce::File(juce::String(source->filePath));
    if (!srcFile.existsAsFile()) return fail("Original source video not found.");

    // ── Trim → absolute source-time cut range ─────────────────────────────
    // region->startTime/endTime bound the region's decode buffer in SOURCE-
    // FILE seconds. Within that buffer, smpStart/smpLength are a FINER trim
    // (Sampler panel drag handles) expressed in ENGINE-BUFFER SAMPLES — i.e.
    // samples of the buffer decoded at the engine's OWN sample rate, which is
    // whatever the audio device negotiated, NOT a fixed 44.1/48 kHz (that
    // exact assumption has shipped a pitch bug in this codebase before — see
    // srFactor in the clip export path). We therefore MEASURE the engine rate
    // at call time and convert smpStart/smpLength → seconds using it:
    //     offsetSec   = smpStart  / engineRate
    //     lengthSec   = smpLength / engineRate     (smpLength == 0 ⇒ to the end)
    //     cutInSec    = region->startTime + offsetSec
    //     cutOutSec   = smpLength > 0 ? cutInSec + lengthSec : region->endTime
    const double engineRate = g_timeline->getSampleRate();
    double cutInSec  = region->startTime;
    double cutOutSec = region->endTime;
    if (engineRate > 0.0) {
        cutInSec = region->startTime + static_cast<double>(region->slot(0).smpStart) / engineRate;
        if (region->slot(0).smpLength > 0) {
            cutOutSec = cutInSec
                      + static_cast<double>(region->slot(0).smpLength) / engineRate;
        }
    }
    cutInSec  = std::clamp(cutInSec,  region->startTime, region->endTime);
    cutOutSec = std::clamp(cutOutSec, cutInSec,           region->endTime);
    if (cutOutSec <= cutInSec) return fail("Trimmed section is empty.");

    std::cout << "[Video Export] region=" << regionId
              << " engineRate=" << engineRate << "Hz"
              << " smpStart=" << region->slot(0).smpStart
              << " smpLength=" << region->slot(0).smpLength
              << " -> cut [" << cutInSec << ", " << cutOutSec << ") of "
              << source->filePath << "\n";

    const std::string format = (info.Length() >= 2 && info[1].IsString())
        ? info[1].As<JsonApi::String>().Utf8Value()
        : "sampleNameOnly";
    const std::string srcStem = srcFile.getFileNameWithoutExtension().toStdString();
    const std::string labelStr = sampleLabelToString(region->label);
    std::string filename = buildExportFilename(srcStem, labelStr, region->name, format, "mov");

    const std::string outputPath = g_projectManager->getExportsDir() + "/" + filename;
    const std::string tempVideoPath = outputPath + ".video.tmp.mov";
    juce::File(juce::String(tempVideoPath)).deleteFile();   // stale leftover from a crashed run

    // ── Video: re-encode the exact section, native resolution, DNxHR HQX ──
    if (!ProxyTranscoder::transcodeSectionHQX(source->filePath, tempVideoPath, cutInSec, cutOutSec)) {
        juce::File(juce::String(tempVideoPath)).deleteFile();
        return fail("Video section encode failed.");
    }

    // ── Audio: decode the same section at the source's native rate ────────
    // (mirrors Audio_ExportRegion — native rate, no resampling artifacts)
    const int nativeRate = probeAudioInfo(source->filePath).sampleRate;
    const juce::AudioBuffer<float>* audioBuf = nullptr;
    const int audioSampleId = sampleBank->loadSampleFromSource(
        source->filePath, cutInSec, cutOutSec, static_cast<double>(nativeRate));
    if (audioSampleId >= 0) audioBuf = sampleBank->getSample(audioSampleId);
    if (!audioBuf || audioBuf->getNumSamples() == 0)
        std::cerr << "[Video Export] No audio decoded for section — exporting video-only.\n";

    // ── Mux video (stream-copy) + audio (fresh PCM encode) into one .mov ──
    auto destFile = juce::File(juce::String(outputPath));
    if (destFile.existsAsFile()) destFile.deleteFile();
    const bool muxOk = muxVideoSectionWithAudio(
        tempVideoPath, audioBuf, static_cast<double>(nativeRate), outputPath);
    juce::File(juce::String(tempVideoPath)).deleteFile();
    if (!muxOk) return fail("Mux failed.");

    const double duration = cutOutSec - cutInSec;
    log.done(filename);

    JsonApi::Object result = JsonApi::Object::New(env);
    result.Set("success",  JsonApi::Boolean::New(env, true));
    result.Set("path",     JsonApi::String::New(env, outputPath));
    result.Set("duration", JsonApi::Number::New(env, duration));
    return result;
}

// video_swapRegionVideo(regionId, replacementFilePath) → { success, swappedPath, durationMismatch }
// Copies the replacement file to swapped/, probes its duration via VideoDecoder,
// then rebinds the region's VIDEO stream ONLY through a single ModifyRegionCommand
// (undoable — mirrors the trim-edit path in Timeline_ModifyRegion). The
// replacement is transcoded through the same on-demand proxy path a normal
// import uses (maybeEnqueueRegionProxy → ProxyTranscoder::transcodeRange), so
// there is no separate/duplicated transcode code. audioFilePath and
// swappedAudioPath are never read or written.
JsonApi::Value Video_SwapRegionVideo(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !g_undoManager || !g_projectManager)
        return fail("Engine not initialised.");
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsString())
        return fail("video_swapRegionVideo(regionId: number, replacementFilePath: string)");
    if (!g_projectManager->hasProjectDir())
        return fail("No project directory — save project first.");

    const int regionId = info[0].As<JsonApi::Number>().Int32Value();
    const std::string srcPath = info[1].As<JsonApi::String>().Utf8Value();
    BridgeCallLog log("video.swapRegionVideo");

    const SampleRegion* region = g_timeline->getRegion(regionId);
    if (!region) return fail("Region not found.");

    auto srcFile = juce::File(juce::String(srcPath));
    if (!srcFile.existsAsFile()) return fail("Replacement file not found.");

    // Probe the replacement BEFORE copying so a non-video file is rejected
    // without touching disk state.
    VideoDecoder probe;
    if (!probe.open(srcPath) || probe.getWidth() <= 0 || probe.getHeight() <= 0) {
        probe.close();
        return fail("Replacement file has no readable video stream.");
    }
    const double replacementDuration = probe.getDuration();
    const double replacementFps      = probe.getFPS();
    const int    replacementWidth    = probe.getWidth();
    const int    replacementHeight   = probe.getHeight();
    probe.close();

    // Copy into swapped/, prefixed so it never collides with a swapped-audio
    // file of the same basename (they share the project's swapped/ dir).
    const std::string destPath = g_projectManager->getSwappedDir() + "/video_"
                                 + std::to_string(regionId) + "_"
                                 + srcFile.getFileName().toStdString();
    auto destFile = juce::File(juce::String(destPath));
    if (destFile.existsAsFile()) destFile.deleteFile();
    if (!srcFile.copyFileTo(destFile)) return fail("File copy to swapped/ failed.");

    // Duration rule: never time-stretch, never resize the clip. If the
    // replacement's own duration differs from the region's timeline duration
    // by more than one frame, clamp playback to the ORIGINAL duration and
    // report the mismatch so the caller can warn the user.
    const double originalDuration = region->getDuration();
    const double fps = replacementFps > 0.0 ? replacementFps
                      : 30.0; // fallback if probe couldn't determine fps
    const double frameSeconds = 1.0 / fps;
    const bool mismatch = std::abs(replacementDuration - originalDuration) > frameSeconds;

    // Snapshot the FULL current region, mutate only the video-swap fields, and
    // commit through UndoManager as one operation — a single undo restores the
    // previous video binding (proxy fields included), nothing else changes.
    SampleRegion newState = *region;
    newState.swappedVideoPath             = destPath;
    newState.hasSwappedVideo              = true;
    newState.swappedVideoDurationSec      = replacementDuration;
    newState.swappedVideoDurationMismatch = mismatch;
    newState.swappedVideoWidth            = replacementWidth;
    newState.swappedVideoHeight           = replacementHeight;

    g_undoManager->execute(
        std::make_unique<ModifyRegionCommand>(regionId, newState, *g_timeline),
        *g_timeline);

    // The old proxy (if any) was transcoded from the OLD video source — drop it
    // and schedule a fresh one from the swapped file via the normal on-demand
    // proxy pipeline (maybeEnqueueRegionProxy reads region->swappedVideoPath
    // when hasSwappedVideo is set).
    invalidateRegionProxy(regionId);
    reenqueueRegionProxy(regionId, /*forceRetranscode=*/true);

    // The regenerated proxy reuses the SAME on-disk path (<proxiesDir>/<regionId>.mxf,
    // keyed by regionId, not content), so the live-preview GPU frame cache
    // (keyed on path+frameIndex) could otherwise keep serving decoded frames
    // from the video we just replaced. A full clear is cheap (frames are
    // re-decoded lazily on next preview tick) and guarantees no stale frames.
    {
        std::lock_guard<std::mutex> lock(g_previewCompositorMutex);
        if (g_previewRenderCache) g_previewRenderCache->clear();
    }

    log.done(destFile.getFileName().toStdString());

    JsonApi::Object result = JsonApi::Object::New(env);
    result.Set("success",          JsonApi::Boolean::New(env, true));
    result.Set("swappedPath",      JsonApi::String::New(env, destPath));
    result.Set("durationMismatch", JsonApi::Boolean::New(env, mismatch));
    result.Set("replacementDurationSec", JsonApi::Number::New(env, replacementDuration));
    result.Set("originalDurationSec",    JsonApi::Number::New(env, originalDuration));
    return result;
}

// video_revertRegionVideo(regionId) → { success }
// Clears the video swap and returns the region to streaming its original
// source video, through the same single-command UndoManager path as swap.
JsonApi::Value Video_RevertRegionVideo(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    auto fail = [&](const char* msg) -> JsonApi::Value {
        JsonApi::Object o = JsonApi::Object::New(env);
        o.Set("success", JsonApi::Boolean::New(env, false));
        o.Set("error",   JsonApi::String::New(env, msg));
        return o;
    };

    if (!isInitialised() || !g_timeline || !g_undoManager)
        return fail("Engine not initialised.");
    if (info.Length() < 1 || !info[0].IsNumber())
        return fail("video_revertRegionVideo(regionId: number)");

    const int regionId = info[0].As<JsonApi::Number>().Int32Value();
    BridgeCallLog log("video.revertRegionVideo");

    const SampleRegion* region = g_timeline->getRegion(regionId);
    if (!region) return fail("Region not found.");

    SampleRegion newState = *region;
    newState.swappedVideoPath             = "";
    newState.hasSwappedVideo              = false;
    newState.swappedVideoDurationSec      = 0.0;
    newState.swappedVideoDurationMismatch = false;

    g_undoManager->execute(
        std::make_unique<ModifyRegionCommand>(regionId, newState, *g_timeline),
        *g_timeline);

    invalidateRegionProxy(regionId);
    reenqueueRegionProxy(regionId, /*forceRetranscode=*/true);

    {
        std::lock_guard<std::mutex> lock(g_previewCompositorMutex);
        if (g_previewRenderCache) g_previewRenderCache->clear();
    }

    log.done(region->name);

    JsonApi::Object result = JsonApi::Object::New(env);
    result.Set("success", JsonApi::Boolean::New(env, true));
    return result;
}

