// source_loadSource(filePath) → { success, duration }
JsonApi::Value Source_LoadSource(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised()) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 1 || !info[0].IsString()) {
        JsonApi::TypeError::New(env, "source_loadSource(filePath: string)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }

    std::string path = info[0].As<JsonApi::String>().Utf8Value();
    BridgeCallLog log("source.loadSource");

    auto& sp = audioEngine->getSourcePlayer();
    const double sampleRate = audioEngine->getSampleRate();
    bool skipped = sp.isCurrentSource(path, sampleRate);
    bool ok = sp.loadSource(path, sampleRate);

    JsonApi::Object o = JsonApi::Object::New(env);
    o.Set("success",  JsonApi::Boolean::New(env, ok));
    o.Set("duration", JsonApi::Number::New(env, ok ? sp.getDuration() : 0.0));
    o.Set("skipped",  JsonApi::Boolean::New(env, skipped && ok));
    log.done(ok ? (skipped ? "skipped" : "ok") : "failed");
    return o;
}

