// source_playRegionPreview(startTime, endTime)
JsonApi::Value Source_PlayRegionPreview(const JsonApi::CallbackInfo& info)
{
    JsonApi::Env env = info.Env();
    if (!isInitialised()) {
        JsonApi::Error::New(env, "Engine not initialised.").ThrowAsJavaScriptException();
        return env.Undefined();
    }
    if (info.Length() < 2 || !info[0].IsNumber() || !info[1].IsNumber()) {
        JsonApi::TypeError::New(env, "source_playRegionPreview(startTime: number, endTime: number)")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }

    const double startTime = info[0].As<JsonApi::Number>().DoubleValue();
    const double endTime = info[1].As<JsonApi::Number>().DoubleValue();
    if (!std::isfinite(startTime) || !std::isfinite(endTime)) {
        JsonApi::RangeError::New(env, "startTime and endTime must be finite")
            .ThrowAsJavaScriptException();
        return env.Undefined();
    }

    BridgeCallLog log("source.playRegionPreview");
    auto& sp = audioEngine->getSourcePlayer();
    const uint64_t seq = sp.playRegionPreview(startTime, endTime);

    JsonApi::Object o = JsonApi::Object::New(env);
    o.Set("started", JsonApi::Boolean::New(env, seq != 0));
    o.Set("seq", JsonApi::Number::New(env, static_cast<double>(seq)));
    o.Set("duration", JsonApi::Number::New(env, std::max(0.0, endTime - startTime)));
    if (seq == 0) {
        o.Set("reason", JsonApi::String::New(env, sp.isLoaded() ? "invalidRange" : "notLoaded"));
    }
    log.done(seq != 0 ? "ok" : "ignored");
    return o;
}

